// What the spreadsheet's numbers look like as a chart.
//
// One selection can be read as a dozen different pictures, and which one is
// right is a question about the numbers rather than about the code - so the
// type is a dropdown, and this module turns one selection plus one type into
// the option object echarts draws. It is pure, which is the point: the shapes
// a selection can take are worth pinning down in tests, because a chart drawn
// from the wrong axis still looks like a chart.
//
// Two rules run through all of it. A gap in the data is a gap, never a zero -
// a missing reading drawn as nothing is a lie about the numbers. And a type
// that cannot show what was selected (a pie of four series) says so by folding
// the series together rather than by drawing the first one and dropping the
// rest silently.

import { shade } from './ganttstyle';

export type ChartSeries = { name: string; points: (number | null)[] };
export type ChartSet = { labels: string[]; series: ChartSeries[] };

export type ChartType =
    | 'line' | 'smooth' | 'step' | 'area' | 'stackedArea'
    | 'bar' | 'stackedBar' | 'hbar' | 'stackedHbar'
    | 'scatter' | 'bubble'
    | 'pie' | 'donut' | 'rose'
    | 'radar' | 'heatmap' | 'boxplot' | 'funnel';

export interface ChartTypeInfo {
    value: ChartType;
    label: string;
    group: string;
    hint: string;
    // Types that fold every series into one total per label, because that is
    // the only thing they can mean.
    folds?: boolean;
}

export const CHART_TYPES: ChartTypeInfo[] = [
    { value: 'smooth', group: 'Lines', label: 'Smooth line', hint: 'Curved through every reading — the one this view has always drawn' },
    { value: 'line', group: 'Lines', label: 'Straight line', hint: 'Point to point, with no curve invented between them' },
    { value: 'step', group: 'Lines', label: 'Step', hint: 'Holds each value until the next — for readings that change rather than drift' },
    { value: 'area', group: 'Lines', label: 'Area', hint: 'A filled line, for one quantity over a run' },
    { value: 'stackedArea', group: 'Lines', label: 'Stacked area', hint: 'The series piled up, so the top edge is the total' },

    { value: 'bar', group: 'Bars', label: 'Bars', hint: 'One bar per series at each label, side by side' },
    { value: 'stackedBar', group: 'Bars', label: 'Stacked bars', hint: 'One bar per label, split by series' },
    { value: 'hbar', group: 'Bars', label: 'Horizontal bars', hint: 'Bars lying down — the one that fits long labels' },
    { value: 'stackedHbar', group: 'Bars', label: 'Stacked horizontal', hint: 'Lying down and piled up' },

    { value: 'scatter', group: 'Points', label: 'Scatter', hint: 'The readings alone, with nothing drawn between them' },
    { value: 'bubble', group: 'Points', label: 'Bubble', hint: 'Scatter with the value in the size of the dot as well as its height' },

    { value: 'pie', group: 'Parts of a whole', label: 'Pie', hint: 'Shares of one total — several series are added together', folds: true },
    { value: 'donut', group: 'Parts of a whole', label: 'Donut', hint: 'A pie with the middle out, which is easier to read', folds: true },
    { value: 'rose', group: 'Parts of a whole', label: 'Rose', hint: 'Shares as petals, sized by value rather than angle', folds: true },
    { value: 'funnel', group: 'Parts of a whole', label: 'Funnel', hint: 'Ordered stages, widest first', folds: true },

    { value: 'radar', group: 'Comparisons', label: 'Radar', hint: 'Every series over the same few labels, as a shape' },
    { value: 'heatmap', group: 'Comparisons', label: 'Heatmap', hint: 'A grid of the whole selection, coloured by value' },
    { value: 'boxplot', group: 'Comparisons', label: 'Box plot', hint: 'The spread of each series: quartiles, whiskers and the middle' },
];

export function chartTypeInfo(t: ChartType): ChartTypeInfo {
    for (const c of CHART_TYPES) if (c.value === t) return c;
    return CHART_TYPES[0];
}

// The colours and inks the chart is drawn with, handed in so that the chart
// follows the app's light and dark rather than deciding for itself.
export interface ChartLook {
    dark: boolean;
    colors: string[];
    text: string;
    faint: string;
    grid: string;
    surface: string;
}

// --- the numbers ------------------------------------------------------------

// Every reading, for working out a range or a spread.
export function allValues(set: ChartSet): number[] {
    const out: number[] = [];
    for (const s of set.series) for (const v of s.points) if (v !== null && isFinite(v)) out.push(v);
    return out;
}

// One total per label, for the types that can only show a whole. Labels that
// total nothing are left out rather than drawn as a slice of zero.
export function foldToTotals(set: ChartSet): { name: string; value: number }[] {
    return set.labels.map((label, i) => {
        let sum = 0;
        let any = false;
        for (const s of set.series) {
            const v = s.points[i];
            if (v !== null && isFinite(v)) { sum += v; any = true; }
        }
        return { name: label, value: any ? sum : 0, any };
    }).filter(d => d.any).map(({ name, value }) => ({ name, value }));
}

// The five numbers a box plot is drawn from. Linear interpolation between
// readings, which is the quartile definition most spreadsheets use.
export function fiveNumbers(values: number[]): [number, number, number, number, number] | null {
    const v = values.filter(x => isFinite(x)).slice().sort((a, b) => a - b);
    if (v.length === 0) return null;
    const q = (p: number) => {
        const pos = (v.length - 1) * p;
        const lo = Math.floor(pos);
        const hi = Math.ceil(pos);
        return lo === hi ? v[lo] : v[lo] + (v[hi] - v[lo]) * (pos - lo);
    };
    return [v[0], q(0.25), q(0.5), q(0.75), v[v.length - 1]];
}

// --- the option -------------------------------------------------------------

// --- the gradients ---------------------------------------------------------
//
// A bar or a slice is a solid shape, and a solid shape in one flat colour is
// the thing that makes a chart look like a screenshot of a chart. A shallow
// gradient gives it a surface.
//
// The depth is a judgement: enough to read as a lit surface across a room,
// not so much that the two ends of one bar look like two different series.
// The middle stop stays the base colour whatever the depth, so what the legend
// swatch shows is still what most of the shape is - which is the thing that
// stops a deeper gradient becoming a lie about the colour.
const LIFT = 0.3;
const DROP = 0.2;

// A bar. The light comes from the end the bar grows out of, which is the top
// for a column and the left for one lying down, so a chart of either reads as
// lit from one place.
export function barGradient(color: string, horizontal: boolean): any {
    return {
        type: 'linear',
        x: 0, y: 0,
        x2: horizontal ? 1 : 0,
        y2: horizontal ? 0 : 1,
        colorStops: [
            { offset: 0, color: shade(color, LIFT) },
            { offset: 0.55, color },
            { offset: 1, color: shade(color, -DROP) },
        ],
    };
}

// A slice. Radial rather than linear: a pie has no top, so a gradient running
// down the whole chart would light some slices and not others. Lifting the
// middle and letting the rim fall away domes each slice on its own terms.
export function sliceGradient(color: string): any {
    return {
        type: 'radial',
        x: 0.5, y: 0.5, r: 0.85,
        colorStops: [
            { offset: 0, color: shade(color, LIFT) },
            { offset: 0.6, color },
            { offset: 1, color: shade(color, -DROP) },
        ],
    };
}

function seriesColor(look: ChartLook, i: number): string {
    return look.colors[((i % look.colors.length) + look.colors.length) % look.colors.length];
}

// A line, in all its varieties. They differ by three flags, so they are one
// function rather than five that would drift apart.
function lineOption(set: ChartSet, type: ChartType, look: ChartLook): any {
    const smooth = type === 'smooth' || type === 'stackedArea' || type === 'area';
    const step = type === 'step';
    const filled = type === 'area' || type === 'stackedArea';
    const stacked = type === 'stackedArea';
    return {
        series: set.series.map((s, i) => {
            const color = seriesColor(look, i);
            return {
                type: 'line',
                name: s.name,
                data: s.points,
                smooth: smooth ? 0.35 : false,
                step: step ? 'end' : false,
                connectNulls: false,
                showSymbol: set.labels.length <= 60,
                symbolSize: 7,
                itemStyle: { color, borderColor: look.surface, borderWidth: 2 },
                lineStyle: {
                    width: 2.25,
                    color,
                    // The dotted line is what this view has always looked like;
                    // it is kept for the smooth one and dropped for the rest,
                    // where a solid line reads better.
                    type: type === 'smooth' ? ([1, 6] as any) : 'solid',
                    cap: 'round',
                },
                ...(stacked ? { stack: 'total' } : {}),
                ...(filled ? {
                    areaStyle: {
                        opacity: 1,
                        color: {
                            type: 'linear', x: 0, y: 0, x2: 0, y2: 1,
                            colorStops: [
                                { offset: 0, color: `${color}47` },
                                { offset: 0.55, color: `${color}17` },
                                { offset: 1, color: `${color}00` },
                            ],
                        },
                    },
                } : {}),
            };
        }),
    };
}

function barOption(set: ChartSet, type: ChartType, look: ChartLook): any {
    const stacked = type === 'stackedBar' || type === 'stackedHbar';
    return {
        series: set.series.map((s, i) => ({
            type: 'bar',
            name: s.name,
            data: s.points,
            ...(stacked ? { stack: 'total' } : {}),
            barMaxWidth: 42,
            itemStyle: {
                color: barGradient(seriesColor(look, i), type === 'hbar' || type === 'stackedHbar'),
                // A stacked bar's segments meet, so only the top of the pile
                // is rounded off; rounding each one would leave gaps down it.
                borderRadius: stacked ? 0 : (type === 'hbar' ? [0, 4, 4, 0] : [4, 4, 0, 0]),
            },
        })),
    };
}

// The chart, as echarts wants it.
//
// `horizontal` swaps the two axes rather than the data, so a horizontal bar
// chart is the same numbers read the same way round - which is what makes the
// tooltip and the legend say the same thing in both.
export function chartOption(set: ChartSet, type: ChartType, look: ChartLook, title: string): any {
    const common = {
        backgroundColor: 'transparent',
        animationDuration: 320,
        textStyle: { color: look.text, fontFamily: 'ui-sans-serif, system-ui, -apple-system, "Segoe UI", Roboto, sans-serif' },
        tooltip: {
            trigger: type === 'scatter' || type === 'bubble' || type === 'heatmap' || type === 'boxplot' ? 'item' : 'axis',
            backgroundColor: look.surface,
            borderColor: look.grid,
            textStyle: { color: look.text, fontSize: 12 },
        },
        grid: { left: 64, right: 28, top: 24, bottom: 52, containLabel: true },
        color: look.colors,
    };

    const catAxis = {
        type: 'category',
        data: set.labels,
        axisLine: { lineStyle: { color: look.grid } },
        axisTick: { show: false },
        axisLabel: { color: look.faint, fontSize: 11, hideOverlap: true },
    };
    const valAxis = {
        type: 'value',
        splitLine: { lineStyle: { color: look.grid, type: [2, 5] as any } },
        axisLine: { show: false },
        axisLabel: { color: look.faint, fontSize: 11 },
    };

    if (type === 'pie' || type === 'donut' || type === 'rose') {
        const data = foldToTotals(set);
        return {
            ...common,
            tooltip: { ...common.tooltip, trigger: 'item', formatter: '{b}: {c} ({d}%)' },
            grid: undefined,
            series: [{
                type: 'pie',
                name: title,
                data: data.map((d, i) => ({
                    ...d,
                    itemStyle: { color: sliceGradient(seriesColor(look, i)) },
                })),
                radius: type === 'donut' ? ['42%', '72%'] : type === 'rose' ? ['18%', '74%'] : '72%',
                roseType: type === 'rose' ? 'area' : undefined,
                itemStyle: { borderColor: look.surface, borderWidth: 2, borderRadius: type === 'rose' ? 0 : 4 },
                label: { color: look.text, fontSize: 11 },
                labelLine: { lineStyle: { color: look.grid } },
            }],
        };
    }

    if (type === 'funnel') {
        return {
            ...common,
            tooltip: { ...common.tooltip, trigger: 'item', formatter: '{b}: {c}' },
            grid: undefined,
            series: [{
                type: 'funnel',
                name: title,
                data: foldToTotals(set).map((d, i) => ({
                    ...d,
                    // A funnel labels inside its own shapes, so the gradient
                    // runs across rather than down: the ink sits on the middle
                    // of the band, which is the base colour.
                    itemStyle: { color: barGradient(seriesColor(look, i), true) },
                })),
                sort: 'descending',
                gap: 2,
                label: { color: look.text, fontSize: 11, position: 'inside' },
                itemStyle: { borderColor: look.surface, borderWidth: 2 },
            }],
        };
    }

    if (type === 'radar') {
        const values = allValues(set);
        const max = values.length > 0 ? Math.max(...values) : 1;
        return {
            ...common,
            tooltip: { ...common.tooltip, trigger: 'item' },
            grid: undefined,
            radar: {
                indicator: set.labels.map(l => ({ name: l, max: max > 0 ? max : 1 })),
                axisName: { color: look.faint, fontSize: 11 },
                splitLine: { lineStyle: { color: look.grid } },
                axisLine: { lineStyle: { color: look.grid } },
                splitArea: { show: false },
            },
            series: [{
                type: 'radar',
                data: set.series.map((s, i) => ({
                    name: s.name,
                    // Radar has no idea what a gap is, so a missing reading is
                    // the only place a zero stands in for one - and the tooltip
                    // still shows the label, so it is visible rather than quiet.
                    value: s.points.map(v => (v === null ? 0 : v)),
                    lineStyle: { color: seriesColor(look, i), width: 2 },
                    itemStyle: { color: seriesColor(look, i) },
                    areaStyle: { color: `${seriesColor(look, i)}22` },
                })),
            }],
        };
    }

    if (type === 'heatmap') {
        const values = allValues(set);
        const lo = values.length > 0 ? Math.min(...values) : 0;
        const hi = values.length > 0 ? Math.max(...values) : 1;
        const data: [number, number, number][] = [];
        set.series.forEach((s, y) => {
            s.points.forEach((v, x) => {
                if (v !== null && isFinite(v)) data.push([x, y, v]);
            });
        });
        return {
            ...common,
            tooltip: { ...common.tooltip, trigger: 'item' },
            grid: { left: 64, right: 28, top: 24, bottom: 80, containLabel: true },
            xAxis: { ...catAxis, splitArea: { show: true } },
            yAxis: {
                type: 'category',
                data: set.series.map(s => s.name),
                axisLine: { lineStyle: { color: look.grid } },
                axisTick: { show: false },
                axisLabel: { color: look.faint, fontSize: 11 },
            },
            visualMap: {
                min: lo, max: hi === lo ? lo + 1 : hi,
                calculable: true,
                orient: 'horizontal',
                left: 'center',
                bottom: 4,
                textStyle: { color: look.faint, fontSize: 11 },
                inRange: { color: look.dark ? ['#1e3a5f', '#4a90d9', '#e2703a'] : ['#e8f0fb', '#4a90d9', '#c0475f'] },
            },
            series: [{
                type: 'heatmap',
                data,
                label: { show: set.labels.length * set.series.length <= 120, color: look.text, fontSize: 10 },
                itemStyle: { borderColor: look.surface, borderWidth: 1 },
            }],
        };
    }

    if (type === 'boxplot') {
        const boxes = set.series.map(s => fiveNumbers(s.points.filter(v => v !== null) as number[]));
        return {
            ...common,
            tooltip: { ...common.tooltip, trigger: 'item' },
            xAxis: {
                type: 'category',
                data: set.series.map(s => s.name),
                axisLine: { lineStyle: { color: look.grid } },
                axisTick: { show: false },
                axisLabel: { color: look.faint, fontSize: 11, hideOverlap: true },
            },
            yAxis: valAxis,
            series: [{
                type: 'boxplot',
                data: boxes.map(b => (b === null ? [0, 0, 0, 0, 0] : b)),
                itemStyle: { color: `${look.colors[0]}33`, borderColor: look.colors[0], borderWidth: 1.5 },
            }],
        };
    }

    if (type === 'scatter' || type === 'bubble') {
        const values = allValues(set);
        const hi = values.length > 0 ? Math.max(...values.map(Math.abs)) : 1;
        return {
            ...common,
            xAxis: catAxis,
            yAxis: valAxis,
            series: set.series.map((s, i) => ({
                type: 'scatter',
                name: s.name,
                data: s.points.map((v, x) => (v === null ? null : [x, v])),
                symbolSize: type === 'bubble'
                    ? (d: any) => 6 + (hi > 0 ? (Math.abs(d[1]) / hi) * 26 : 0)
                    : 9,
                itemStyle: { color: seriesColor(look, i), opacity: type === 'bubble' ? 0.68 : 0.95 },
            })),
        };
    }

    const horizontal = type === 'hbar' || type === 'stackedHbar';
    const built = type === 'bar' || type === 'stackedBar' || horizontal
        ? barOption(set, type, look)
        : lineOption(set, type, look);

    return {
        ...common,
        xAxis: horizontal ? valAxis : catAxis,
        yAxis: horizontal ? { ...catAxis, inverse: true } : valAxis,
        ...built,
    };
}
