// The search box, with the expression language's own vocabulary behind it.
//
// Three things it does that a plain input does not: it finishes a bracket or a
// quote and leaves the caret inside, it offers the functions a half-typed word
// could become, and it says what each of them is for. Inside a function's
// quotes it offers what that argument can be - the keywords for IsStatus, the
// tags for HasTags, the property names and then their values for
// MatchProperty - and after `{{` the yaml's filters. The rules themselves are
// in `orgquery.ts` and are tested there - this is the keyboard and the popup.
//
// The popup is not a Joy `Menu`: a menu takes the focus, and a suggestion list
// that takes the focus out of the box you are typing in is a suggestion list
// that fights you. It is a plain sheet positioned under the input, and every
// key that matters is handled on the input itself.

import * as React from 'react';
import Box from '@mui/joy/Box';
import Sheet from '@mui/joy/Sheet';
import Input from '@mui/joy/Input';
import Typography from '@mui/joy/Typography';
import Chip from '@mui/joy/Chip';

import {
    Suggestion, GROUP_COLORS,
    suggestAt, applySuggestion, typePair, backspacePair,
} from '../orgquery';
import useQueryVocab from '../useQueryVocab';

// More function names than this and the list is a wall rather than a
// suggestion. Values (tags, properties, ...) are not capped here - the list
// scrolls, and the one being looked for may sort late - only kept to a size
// the browser draws without noticing.
const MOST = 8;
const MOST_VALUES = 200;

export default function QueryBox(props: {
    value: string;
    onChange: (v: string) => void;
    onEnter?: () => void;
    placeholder?: string;
    startDecorator?: React.ReactNode;
    size?: 'sm' | 'md' | 'lg';
    sx?: any;
}) {
    const inputRef = React.useRef<HTMLInputElement | null>(null);
    const [caret, setCaret] = React.useState(0);
    const [open, setOpen] = React.useState(false);
    const [pick, setPick] = React.useState(0);

    const vocab = useQueryVocab();
    const found = React.useMemo(
        () => suggestAt(props.value, caret, vocab, MOST),
        [props.value, caret, vocab],
    );
    const options = found.options.slice(0, MOST_VALUES);
    const showing = open && options.length > 0;

    React.useEffect(() => { setPick(0); }, [found.word]);

    // Arrowing down a list of two hundred tags has to keep the chosen one in
    // view, or the highlight walks off the bottom of the sheet.
    const listRef = React.useRef<HTMLDivElement | null>(null);
    React.useEffect(() => {
        const row = listRef.current?.children[pick] as HTMLElement | undefined;
        if (row) row.scrollIntoView({ block: 'nearest' });
    }, [pick]);

    // Where the caret has to end up once React has put the new value in the
    // input, or -1 for "wherever it already is".
    const pending = React.useRef(-1);

    // Put the text back with the caret where the rule asked for it.
    //
    // React owns the value, and writing a value into an input puts the caret at
    // the end of it - so an auto-inserted closing bracket would leave the caret
    // after it rather than inside it. The correction has to happen after React
    // has written the value and before the frame is painted, which is what a
    // layout effect is. It was a requestAnimationFrame first, and that races:
    // the frame can be scheduled before React commits, and then the caret is
    // set and immediately thrown away again.
    const put = (text: string, at: number) => {
        // Stepping over a closer changes the caret and nothing else. React does
        // not re-render for a value it already has, so the effect below would
        // never run and the caret would sit still - and then the next character
        // typed goes in on the wrong side of the bracket.
        if (text === props.value) {
            const el = inputRef.current;
            if (el) {
                el.selectionStart = at;
                el.selectionEnd = at;
            }
            setCaret(at);
            return;
        }
        pending.current = at;
        props.onChange(text);
    };

    React.useLayoutEffect(() => {
        if (pending.current < 0) return;
        const at = pending.current;
        pending.current = -1;
        const el = inputRef.current;
        if (!el) return;
        el.selectionStart = at;
        el.selectionEnd = at;
        setCaret(at);
    });

    const take = (s: Suggestion) => {
        const r = applySuggestion(props.value, s);
        setOpen(false);
        put(r.text, r.caret);
    };

    const onKeyDown = (e: React.KeyboardEvent<HTMLInputElement>) => {
        const el = e.currentTarget;
        const start = el.selectionStart ?? 0;
        const end = el.selectionEnd ?? start;

        if (showing) {
            if (e.key === 'ArrowDown') {
                e.preventDefault();
                setPick(p => (p + 1) % options.length);
                return;
            }
            if (e.key === 'ArrowUp') {
                e.preventDefault();
                setPick(p => (p - 1 + options.length) % options.length);
                return;
            }
            // Tab takes the suggestion; Enter takes it too, because the list
            // being up means the query is not finished being typed.
            if (e.key === 'Tab' || e.key === 'Enter') {
                e.preventDefault();
                take(options[pick]);
                return;
            }
            if (e.key === 'Escape') {
                e.preventDefault();
                setOpen(false);
                return;
            }
        }

        if (e.key === 'Enter') {
            if (props.onEnter) props.onEnter();
            return;
        }

        if (e.key === 'Backspace') {
            const r = backspacePair(props.value, start, end);
            if (r) {
                e.preventDefault();
                put(r.text, r.caret);
            }
            return;
        }

        // One printable character: the brackets and quotes rule.
        if (e.key.length === 1 && !e.ctrlKey && !e.metaKey && !e.altKey) {
            const r = typePair(props.value, start, end, e.key);
            if (r) {
                e.preventDefault();
                put(r.text, r.caret);
                setOpen(true);
            }
        }
    };

    const follow = (e: React.SyntheticEvent<HTMLInputElement>) => {
        setCaret(e.currentTarget.selectionStart ?? 0);
    };

    return (
        <Box sx={{ position: 'relative', ...(props.sx || {}) }}>
            <Input
                size={props.size || 'sm'}
                slotProps={{ input: { ref: inputRef, spellCheck: false, autoComplete: 'off' } }}
                value={props.value}
                placeholder={props.placeholder}
                startDecorator={props.startDecorator}
                onChange={e => { props.onChange(e.target.value); setCaret(e.target.selectionStart ?? 0); setOpen(true); }}
                onKeyDown={onKeyDown}
                onKeyUp={follow}
                onClick={follow}
                onFocus={() => setOpen(true)}
                // Not on blur directly: a click on the list blurs the input
                // before the click lands, and closing here would take the list
                // away from under the pointer.
                onBlur={() => window.setTimeout(() => setOpen(false), 120)}
                sx={{ fontFamily: 'var(--joy-fontFamily-code, monospace)', fontSize: 13 }}
            />

            {showing && (
                <Sheet
                    variant="outlined"
                    sx={{
                        position: 'absolute', top: '100%', left: 0, right: 0, mt: 0.5,
                        zIndex: 20, borderRadius: 'sm', boxShadow: 'md',
                        display: 'flex', flexDirection: 'column', maxHeight: 320,
                    }}
                >
                    <Box ref={listRef} sx={{ overflowY: 'auto', p: 0.5, minHeight: 0 }}>
                    {options.map((fn, i) => (
                        <Box
                            key={fn.key}
                            // Chosen on mousedown rather than click: click comes
                            // after blur, and by then the list is going away.
                            onMouseDown={e => { e.preventDefault(); take(fn); }}
                            onMouseEnter={() => setPick(i)}
                            sx={{
                                display: 'flex', alignItems: 'baseline', gap: 1,
                                px: 1, py: 0.625, borderRadius: 'sm', cursor: 'pointer',
                                background: i === pick ? 'var(--joy-palette-neutral-softBg)' : 'transparent',
                            }}
                        >
                            <Chip
                                size="sm"
                                variant="soft"
                                color={(GROUP_COLORS[fn.group] || 'neutral') as any}
                                sx={{ '--Chip-minHeight': '16px', fontSize: 9, flexShrink: 0 }}
                            >
                                {fn.group}
                            </Chip>
                            <Box sx={{ minWidth: 0, flex: 1 }}>
                                <Typography
                                    level="body-sm"
                                    sx={{ fontFamily: 'var(--joy-fontFamily-code, monospace)', fontSize: 12.5 }}
                                >
                                    <Box component="span" sx={{ fontWeight: 'lg' }}>{fn.label}</Box>
                                    {fn.args !== undefined && (
                                        <Box component="span" sx={{ color: 'text.tertiary' }}>({fn.args})</Box>
                                    )}
                                </Typography>
                                <Typography level="body-xs" sx={{ color: 'text.tertiary' }} noWrap>
                                    {fn.summary}
                                </Typography>
                            </Box>
                        </Box>
                    ))}
                    </Box>
                    {/* Outside the scroller: eight suggestions would otherwise
                        push what the keys do off the bottom of the list. */}
                    <Typography
                        level="body-xs"
                        sx={{
                            color: 'text.tertiary', px: 1, py: 0.5, fontSize: 10,
                            borderTop: '1px solid', borderColor: 'divider', flexShrink: 0,
                        }}
                    >
                        ↑↓ to choose · tab or enter to take it · esc to leave it
                    </Typography>
                </Sheet>
            )}
        </Box>
    );
}
