// The gantt chart worg draws itself.
//
// Plain svg and no chart library, the way LinkGraph and CellChart are drawn: a
// gantt is rectangles against a date axis, and a library to place rectangles
// costs more than it saves - while the thing we actually want from it, dragging
// a bar to change what a heading says, is not something a chart library would
// give us anyway.
//
// Nothing here writes. Every gesture ends in a callback carrying the task and
// the new value; the page turns that into an org write and refetches. So a bar
// that moved on screen but failed to save snaps back on the next refresh, which
// is the honest outcome - the chart is a view of the files, never a copy.

import * as React from 'react';
import {
    GanttModel, GanttTask, GanttMarker, startOfDay, daySpan, xOf, dayKey, markerDash, shapePath,
    BarRule, BarStyle, BarFill, PLAIN_BAR, barStyleFor, isSymbolShape, wavyBarPath, TaskHealth,
} from '../gantt';
import {
    barGradientStops, barGradientId, shade, contrastText, legibleOn, veilOn, mix, TYPE, NUMERIC,
} from '../ganttstyle';
import { ColorScheme } from '../ganttcolor';

// How a set of marker lines is drawn: chosen by the user, per saved view.
export interface MarkerLook {
    color: string;
    style: string;
    width: number;
}

export interface GanttColors {
    background: string;
    taskDefault: string;
    taskActive: string;
    taskDone: string;
    taskCrit: string;
    sectionAlt: string;
    text: string;
}

// The names column and the margin, exported because the page scrolls this
// chart to a date and has to know where a date lands in it.
export const LABEL_WIDTH = 210;
const ROW_HEIGHT = 29;
const BAR_HEIGHT = 18;
const SECTION_HEIGHT = 24;
const AXIS_HEIGHT = 40;
const TITLE_HEIGHT = 34;
export const PAD = 12;
const TODAY_COLOR = '#e74c3c';
const DAY_MS = 86400000;
// How near the end of a bar counts as the handle rather than the bar.
const GRIP = 7;
// The grab handle at the start of a row.
const GRIP_W = 17;
// What "and this one too" is called on this machine, for the tooltip.
const MOD = typeof navigator !== 'undefined' && /Mac|iPhone|iPad/.test(navigator.platform) ? '⌘' : 'ctrl';

const MONTHS = ['Jan', 'Feb', 'Mar', 'Apr', 'May', 'Jun', 'Jul', 'Aug', 'Sep', 'Oct', 'Nov', 'Dec'];

// Where a day sits across the plot, in the scroll container's own coordinates.
// The page uses this to put a date under the eye; the chart uses it to draw.
export function xForDate(d: Date, spanStart: Date, dayWidth: number): number {
    return LABEL_WIDTH + PAD + xOf(d, spanStart, dayWidth);
}

function fmtDay(d: Date): string {
    return `${d.getDate()} ${MONTHS[d.getMonth()]}`;
}

function fmtDays(n: number): string {
    return n % 1 === 0 ? String(n) : n.toFixed(1);
}

// What colour a bar is depends on the scheme the toolbar has chosen - by state,
// by assignee, by lane, by any property - so the chart no longer decides it.


// What a bar is, in one line. The planned length and the width only differ when
// the bar has stepped over days nobody works, and saying both is the only way
// that reads as arithmetic rather than as a mistake.
function tipFor(t: GanttTask): string {
    const when = `${dayKey(t.start)} → ${dayKey(t.end)}`;
    if (t.milestone || t.mark) return `${t.name}\n${when}`;
    const head = `${t.name}${t.status ? ` [${t.status}]` : ''}`;
    if (t.plannedDays !== null && Math.abs(t.plannedDays - t.days) > 0.01) {
        return `${head}\n${when}\n${fmtDays(t.plannedDays)}d of work across ${fmtDays(t.days)} days`;
    }
    return `${head}\n${when}  (${fmtDays(t.days)}d)`;
}

function textWidth(s: string, px: number): number {
    return s.length * px * 0.58;
}

interface Tick { d: Date; label: string; major: boolean; }

// The axis steps by whatever keeps the labels apart: days while there is room
// for them, then weeks, then months.
function ticksFor(start: Date, end: Date, dayWidth: number): Tick[] {
    const days = daySpan(start, end);
    const out: Tick[] = [];
    if (dayWidth >= 18) {
        for (let i = 0; i <= days; i++) {
            const d = new Date(start.getFullYear(), start.getMonth(), start.getDate() + i);
            out.push({ d, label: String(d.getDate()), major: d.getDay() === 1 || d.getDate() === 1 });
        }
        return out;
    }
    if (dayWidth * 7 >= 40) {
        for (let i = 0; i <= days; i++) {
            const d = new Date(start.getFullYear(), start.getMonth(), start.getDate() + i);
            if (d.getDay() !== 1 && i !== 0) continue;
            out.push({ d, label: fmtDay(d), major: d.getDate() <= 7 });
        }
        return out;
    }
    const first = new Date(start.getFullYear(), start.getMonth(), 1);
    for (let m = 0; ; m++) {
        const d = new Date(first.getFullYear(), first.getMonth() + m, 1);
        if (d > end) break;
        out.push({ d, label: `${MONTHS[d.getMonth()]} ${String(d.getFullYear()).slice(2)}`, major: d.getMonth() === 0 });
    }
    return out;
}

// The stretch of calendar the chart draws: the plan, any window it has been
// pointed at, and markers just past either end - a release the week after the
// last task is the point of the marker - but only within a month, so a marker
// query that finds every milestone ever does not stretch the chart across
// years. Exported because the page scrolls the chart to dates and has to
// measure from the same first day, or every jump lands a few days off.
export function chartSpan(
    model: GanttModel,
    span?: { start: Date; end: Date },
    markers?: GanttMarker[],
): { start: Date; end: Date } {
    const reach = 30 * DAY_MS;
    let lo = span && span.start < model.start ? span.start : model.start;
    let hi = span && span.end > model.end ? span.end : model.end;
    for (const m of markers || []) {
        const mEnd = m.end || new Date(m.date.getTime() + DAY_MS);
        if (m.date < lo && m.date.getTime() >= model.start.getTime() - reach) lo = m.date;
        if (mEnd > hi && mEnd.getTime() <= model.end.getTime() + reach) hi = mEnd;
    }
    return { start: startOfDay(lo), end: hi };
}

// How tall the pinned header is, and where a row sits. Exported together with
// `layoutRows` because the page has to work out which rows are actually on
// screen - and doing that from a second copy of this arithmetic is how the two
// quietly stop agreeing.
export const HEAD_HEIGHT = TITLE_HEIGHT + AXIS_HEIGHT;

type Row =
    // A lane heading. When it is shut it carries a roll-up: the span of
    // everything inside it, so a closed lane still says when its work happens
    // rather than leaving a blank line where a fortnight used to be.
    | { kind: 'section'; name: string; shut: boolean; rollup: { start: Date; end: Date; count: number } | null }
    | { kind: 'task'; task: GanttTask };
type Placed = { row: Row; y: number; h: number };

type Drag =
    | { kind: 'move'; hash: string; fromX: number; dx: number }
    | { kind: 'resize'; hash: string; fromX: number; dx: number }
    | { kind: 'link'; hash: string; side: 'left' | 'right'; x: number; y: number; overHash: string }
    // Rows on the move: which ones, where the pointer is, and where they would
    // land if it were let go now.
    | { kind: 'rows'; hashes: string[]; y: number; lane: string; index: number }
    // A stretch of calendar being swept out with shift held, to zoom to.
    | { kind: 'zoom'; x0: number; x1: number };

// What overdue and slipping look like. Red and amber because those are what
// trouble looks like everywhere else, and they are said in words beside the
// bar too, so the colour is never the only way of telling.
export const HEALTH_COLOR = { overdue: '#e74c3c', slipping: '#e67e22' };

// Every row the chart draws, in order, with where it sits. One function, so the
// chart and anything asking questions about the chart look at the same list.
export function layoutRows(
    model: GanttModel,
    shut: Set<string>,
): { rows: Row[]; placed: Placed[]; bodyHeight: number } {
    const rows: Row[] = [];
    for (const sec of model.sections) {
        const drawn = sec.tasks.filter(t => !t.mark);
        if (drawn.length === 0) continue;
        // A lane with no name cannot be shut: there is no heading to click.
        const isShut = !!sec.name && shut.has(sec.name);
        if (sec.name) {
            let lo: Date | null = null;
            let hi: Date | null = null;
            for (const t of drawn) {
                if (!lo || t.start < lo) lo = t.start;
                if (!hi || t.end > hi) hi = t.end;
            }
            rows.push({
                kind: 'section',
                name: sec.name,
                shut: isShut,
                rollup: isShut && lo && hi ? { start: lo, end: hi, count: drawn.length } : null,
            });
        }
        if (isShut) continue;
        for (const t of drawn) rows.push({ kind: 'task', task: t });
    }
    let y = 0;
    const placed: Placed[] = [];
    for (const row of rows) {
        const h = row.kind === 'section'
            ? (row.shut ? SECTION_HEIGHT + 6 : SECTION_HEIGHT)
            : ROW_HEIGHT;
        placed.push({ row, y, h });
        y += h;
    }
    return { rows, placed, bodyHeight: y };
}

// The work a set of row bands covers. A lane heading that is shut stands in for
// everything inside it, because its roll-up bracket is still on screen showing
// that work's extent - so framing what is visible has to count it.
export function tasksInRows(rows: Placed[], model: GanttModel): GanttTask[] {
    const out: GanttTask[] = [];
    for (const p of rows) {
        if (p.row.kind === 'task') { out.push(p.row.task); continue; }
        const row = p.row;
        if (!row.shut) continue;
        const sec = model.sections.find(x => x.name === row.name);
        if (sec) out.push(...sec.tasks.filter(t => !t.mark));
    }
    return out;
}

export default function ReactGantt({
    model,
    colors,
    scheme,
    title,
    dayWidth,
    span,
    selected,
    readOnly,
    collapsed,
    onToggleLane,
    onSelect,
    onMove,
    onResize,
    onLink,
    picked,
    onPick,
    onReorderRows,
    markers,
    markerLook,
    barRules,
    critical,
    healthOf,
    baselineOf,
    onZoomRange,
    onBarMenu,
}: {
    model: GanttModel;
    colors: GanttColors;
    scheme: ColorScheme;
    title: string;
    dayWidth: number;
    // A stretch of calendar the chart must cover even where it holds no tasks.
    span?: { start: Date; end: Date };
    selected?: string;
    readOnly?: boolean;
    // The lanes that are shut, by name.
    collapsed?: string[];
    onToggleLane?: (name: string) => void;
    // The rows picked up for moving, by hash. Selection lives above this
    // component so it survives the refetch after a write.
    picked?: string[];
    onPick?: (hashes: string[]) => void;
    onSelect?: (t: GanttTask) => void;
    // Dropped somewhere else on the calendar: this is the new start date.
    onMove?: (t: GanttTask, start: Date) => void;
    // Dragged by its right edge: this is the new length in days.
    onResize?: (t: GanttTask, days: number) => void;
    // Dragged from one bar's end handle onto another bar: the one dropped on
    // is the one that waits, which is the way the arrow will be drawn.
    onLink?: (waits: GanttTask, on: GanttTask) => void;
    // Dropped somewhere else in the list: these rows, in this lane, starting at
    // this position. One call for however many rows were dragged, so the whole
    // move is one write and one undo.
    onReorderRows?: (moved: GanttTask[], lane: string, index: number) => void;
    // Lines down the whole chart at moments the plan is read against, from a
    // second query. Drawn in the colour and dash the user picked.
    markers?: GanttMarker[];
    markerLook?: MarkerLook;
    // Outline, fill and shape for the bars of the headings these rules match.
    barRules?: BarRule[];
    // The critical path's task ids: haloed, with their arrows drawn red.
    critical?: Set<string>;
    // Overdue and slipping: a note beside the bar and a tinted row.
    healthOf?: (t: GanttTask) => TaskHealth | null;
    // Where a baseline had this task, drawn as a ghost bar under it.
    baselineOf?: (t: GanttTask) => { start: Date; end: Date } | null;
    // Swept out with shift held: zoom the chart to these dates.
    onZoomRange?: (start: Date, end: Date) => void;
    // A right click on a bar, at this point on the screen.
    onBarMenu?: (t: GanttTask, x: number, y: number) => void;
}) {
    const [hover, setHover] = React.useState<string>('');
    const shut = React.useMemo(() => new Set(collapsed || []), [collapsed]);
    const chosen = React.useMemo(() => new Set(picked || []), [picked]);
    // Where a shift-click measures its range from.
    const anchorRef = React.useRef<string>('');
    const barColor = React.useCallback((t: GanttTask) => scheme.color(t), [scheme]);
    const [drag, setDrag] = React.useState<Drag | null>(null);
    const svgRef = React.useRef<SVGSVGElement>(null);
    // The names column and the chart's title ride sideways with the scroll so
    // they stay put. Moved imperatively rather than through state: a scroll
    // fires on every frame, and re-rendering forty rows to hold a column still
    // is how a chart starts to feel heavy.
    const namesRef = React.useRef<SVGGElement>(null);
    const titleRef = React.useRef<SVGGElement>(null);
    React.useEffect(() => {
        const box = svgRef.current?.parentElement;
        if (!box) return;
        const pin = () => {
            const t = `translate(${box.scrollLeft}, 0)`;
            if (namesRef.current) namesRef.current.setAttribute('transform', t);
            if (titleRef.current) titleRef.current.setAttribute('transform', t);
        };
        pin();
        box.addEventListener('scroll', pin, { passive: true });
        return () => box.removeEventListener('scroll', pin);
    });

    // What stretch of calendar is drawn. Normally the tasks decide it, but a
    // chart asked to show a quarter has to draw that quarter whether or not
    // anything is happening in it - so the requested window is unioned in
    // rather than replacing, which keeps every task reachable by scrolling.
    const { start: spanStart, end: spanEnd } = chartSpan(model, span, markers);
    const start = spanStart;
    const days = daySpan(spanStart, spanEnd);
    const plotWidth = Math.max(days * dayWidth, 120);
    let width = Math.max(LABEL_WIDTH + plotWidth + PAD * 2, textWidth(title, 16) + PAD * 2);

    // Rows are laid out from zero: the title and the axis live in a header of
    // their own that stays at the top of the viewport while this scrolls, so
    // the body cannot carry their height any more.
    const { rows, placed, bodyHeight } = layoutRows(model, shut);
    const marks = model.tasks.filter(t => t.mark);
    let y = bodyHeight;
    const headHeight = HEAD_HEIGHT;
    const plotTop = 0;
    const plotBottom = y;
    const height = y + PAD;

    const ticks = ticksFor(start, spanEnd, dayWidth);
    const x0 = LABEL_WIDTH + PAD;
    const px = (d: Date) => x0 + xOf(d, start, dayWidth);
    const rowOf = new Map<string, Placed>();
    for (const p of placed) if (p.row.kind === 'task' && p.row.task.hash) rowOf.set(p.row.task.hash, p);

    const shaded: Date[] = [];
    for (let i = 0; i < days; i++) {
        const d = new Date(start.getFullYear(), start.getMonth(), start.getDate() + i);
        const wd = d.getDay();
        const weekend = model.excludeWeekends && (wd === 0 || wd === 6);
        if (weekend || model.excludeWeekdays.indexOf(wd) >= 0 || model.excludeDates.indexOf(dayKey(d)) >= 0) {
            shaded.push(d);
        }
    }

    const now = new Date();
    // Compared by the day rather than by the moment: `now` carries a time of
    // day and the span's last day does not, so at any hour past midnight today
    // read as *after* a chart that ends today and the marker vanished on the
    // one day it matters most.
    const todayDay = startOfDay(now);
    const todayX = todayDay >= start && todayDay <= startOfDay(spanEnd) ? px(now) : null;

    // The markers on the drawn span, and where each one's label goes. Labels
    // live in the header's title band, which is empty right of the pinned
    // title, and alternate between two lines when they would run into each
    // other - markers a few days apart are common (a freeze and the release).
    const look: MarkerLook = markerLook || { color: '#8e44ad', style: 'dashed', width: 1.5 };
    const dash = markerDash(look.style, look.width);
    // A band (a marker with an end) is shown when any of it is on the chart.
    const shown = (markers || []).filter(m =>
        (m.end || m.date) >= start && startOfDay(m.date) <= startOfDay(spanEnd));
    const lineEnds = [-Infinity, -Infinity];
    const placedMarkers = shown.map(m => {
        const mx = px(m.date);
        // A shape sits on the line ahead of the name, which moves along.
        const shaped = !!m.shape && m.shape !== 'none';
        const w = textWidth(m.name, TYPE.note.size) + (shaped ? 16 : 8);
        // A marker on the last day would have its label cut off by the edge
        // of the paper, so the paper is widened to hold it.
        width = Math.max(width, mx + w + PAD);
        const lane = mx >= lineEnds[0] ? 0 : mx >= lineEnds[1] ? 1 : (lineEnds[0] <= lineEnds[1] ? 0 : 1);
        lineEnds[lane] = mx + w;
        return { m, mx, mx2: m.end ? px(m.end) : mx, lane, shaped, color: m.color || look.color };
    });

    // One gradient def per colour actually on the chart, rather than one per
    // bar: a plan with forty TODOs in it is one blue, not forty.
    const barColors: string[] = [];
    for (const t of model.tasks) {
        if (t.mark) continue;
        const c = barColor(t);
        if (barColors.indexOf(c) < 0) barColors.push(c);
    }

    // Each bar's style from the rules, worked out once per draw. A bar the
    // query did not find keeps its own hatching: it is already saying
    // something with its fill, and that is the more important thing to say.
    const styleOf = new Map<string, BarStyle>();
    const patterns: { fill: BarFill; color: string }[] = [];
    for (const t of model.tasks) {
        if (t.mark) continue;
        const st = t.implied ? PLAIN_BAR : barStyleFor(t, barRules || []);
        styleOf.set(t.id, st);
        if (st.fill === 'solid' || st.fill === 'hollow') continue;
        const c = barColor(t);
        if (!patterns.some(x => x.fill === st.fill && x.color === c)) patterns.push({ fill: st.fill, color: c });
    }
    const styleFor = (t: GanttTask): BarStyle => styleOf.get(t.id) || PLAIN_BAR;
    const patternId = (fill: BarFill, color: string) => `rgp-${fill}-${color.replace(/[^0-9a-z]/gi, '')}`;
    // The colour laid under a pattern: the bar's colour washed most of the way
    // towards the chart's ground, so the pattern is the bar's colour on a pale
    // version of itself and the hue still says what the colour scheme says.
    const washOf = (color: string) => mix(color, colors.background, 0.6);
    const fillOf = (t: GanttTask): string => {
        if (t.implied) return 'url(#rg-implied)';
        const st = styleFor(t);
        const c = barColor(t);
        if (st.fill === 'hollow') return colors.background;
        if (st.fill !== 'solid') return `url(#${patternId(st.fill, c)})`;
        return `url(#${barGradientId('rg', c)})`;
    };

    // No text colour on this chart is written down. The page's ink is the
    // user's text colour when it can be read on the user's background and ink
    // or paper when it cannot; a label on a bar is read against the bar.
    const ink = legibleOn(colors.text, colors.background);
    const laneInk = legibleOn(colors.text, colors.sectionAlt);
    const hair = (a: number) => veilOn(colors.background, a);

    // --- dragging ----------------------------------------------------------

    const at = (e: React.PointerEvent): { x: number; y: number } => {
        const r = svgRef.current?.getBoundingClientRect();
        return { x: e.clientX - (r ? r.left : 0), y: e.clientY - (r ? r.top : 0) };
    };

    // Whole days only. A gantt bar means a day, and half a day of pointer slop
    // would write a date nobody chose.
    const daysFromPx = (dx: number) => Math.round(dx / dayWidth);

    const taskAtY = (yy: number): GanttTask | null => {
        for (const p of placed) {
            if (p.row.kind === 'task' && yy >= p.y && yy < p.y + p.h) return p.row.task;
        }
        return null;
    };

    // A row can be picked up when it is really a row of this plan: the hatched
    // ones are only here because something waits on them, and have no place of
    // their own to be moved to.
    const grippable = (t: GanttTask) => !readOnly && !t.implied && !!t.hash && !!onReorderRows;

    // The list as the eye reads it, which is the order a shift-click measures a
    // range in.
    const visibleHashes = (): string[] =>
        placed
            .filter(p => p.row.kind === 'task')
            .map(p => ((p.row as any).task as GanttTask).hash || '')
            .filter(Boolean);

    const beginRowDrag = (e: React.PointerEvent, t: GanttTask) => {
        if (!grippable(t)) return;
        const hash = t.hash as string;
        let next: string[];
        if (e.shiftKey && anchorRef.current) {
            // A range, from wherever the last plain pick was.
            const all = visibleHashes();
            const a = all.indexOf(anchorRef.current);
            const b = all.indexOf(hash);
            next = a < 0 || b < 0 ? [hash] : all.slice(Math.min(a, b), Math.max(a, b) + 1);
        } else if (e.metaKey || e.ctrlKey) {
            next = chosen.has(hash)
                ? (picked || []).filter(h => h !== hash)
                : [...(picked || []), hash];
            anchorRef.current = hash;
        } else if (chosen.has(hash)) {
            // Already part of the selection: the whole selection travels.
            next = picked || [hash];
        } else {
            next = [hash];
            anchorRef.current = hash;
        }
        if (onPick) onPick(next);
        const hashes = next.indexOf(hash) >= 0 ? next : [hash];
        const here = at(e);
        const to = dropAt(here.y);
        beginDrag(e, {
            kind: 'rows',
            hashes,
            y: here.y,
            lane: to ? to.lane : t.section,
            index: to ? to.index : 0,
        });
    };

    const beginDrag = (e: React.PointerEvent, d: Drag) => {
        if (readOnly) return;
        e.stopPropagation();
        // Capture keeps the drag alive if the pointer wanders off the element
        // it started on, but it is not what makes the drag work - the svg's own
        // move and up handlers do that - so a browser that refuses it (or a
        // synthetic event with no real pointer behind it) must not take the
        // whole gesture down with it.
        try {
            (e.target as Element).setPointerCapture?.(e.pointerId);
        } catch {
            // No capture; the drag still runs while the pointer is over the chart.
        }
        setDrag(d);
    };

    // Where a set of rows would land if the pointer were let go here: which
    // lane, and how far down it. Measured against the rows as drawn, with the
    // rows being moved left in place - taking them out first would make the
    // list jump under the pointer that is aiming at it.
    const dropAt = (yy: number): { lane: string; index: number } | null => {
        let lane = '';
        let hit: Placed | null = null;
        for (const p of placed) {
            if (yy >= p.y && yy < p.y + p.h) { hit = p; break; }
        }
        if (!hit) {
            // Past the bottom: the end of the last lane.
            const last = placed[placed.length - 1];
            if (!last) return null;
            hit = last;
            yy = last.y + last.h;
        }
        if (hit.row.kind === 'section') {
            return { lane: hit.row.name, index: 0 };
        }
        lane = hit.row.task.section;
        const rows = placed.filter(p => p.row.kind === 'task' && (p.row as any).task.section === lane);
        const at = rows.findIndex(p => p === hit);
        const below = yy > hit.y + hit.h / 2;
        return { lane, index: Math.max(0, at + (below ? 1 : 0)) };
    };

    // Shift and drag across empty chart sweeps out a stretch of calendar to
    // zoom to. Bars, grips and handles take their own pointer down first and
    // stop it here, so a shift-drag that starts on a row grip still picks up
    // a range of rows as it always did.
    const beginZoom = (e: React.PointerEvent) => {
        if (!e.shiftKey || e.button !== 0 || !onZoomRange) return;
        const p = at(e);
        const scrolled = svgRef.current?.parentElement?.scrollLeft || 0;
        // Not from the names column, which is pinned over the plot.
        if (p.x < scrolled + LABEL_WIDTH + PAD) return;
        e.preventDefault();
        try {
            (e.currentTarget as Element).setPointerCapture?.(e.pointerId);
        } catch {
            // As for the other drags: capture helps, but is not needed.
        }
        setDrag({ kind: 'zoom', x0: p.x, x1: p.x });
    };

    const onPointerMove = (e: React.PointerEvent) => {
        if (!drag) return;
        const p = at(e);
        if (drag.kind === 'zoom') {
            setDrag({ ...drag, x1: p.x });
        } else if (drag.kind === 'move' || drag.kind === 'resize') {
            setDrag({ ...drag, dx: p.x - drag.fromX });
        } else if (drag.kind === 'link') {
            const over = taskAtY(p.y);
            setDrag({ ...drag, x: p.x, y: p.y, overHash: over?.hash || '' });
        } else if (drag.kind === 'rows') {
            const to = dropAt(p.y);
            setDrag({ ...drag, y: p.y, lane: to ? to.lane : drag.lane, index: to ? to.index : drag.index });
        }
    };

    const dateAtX = (xx: number): Date => new Date(start.getTime() + ((xx - x0) / dayWidth) * DAY_MS);

    const endDrag = () => {
        if (!drag) return;
        if (drag.kind === 'zoom') {
            setDrag(null);
            const lo = Math.min(drag.x0, drag.x1);
            const hi = Math.max(drag.x0, drag.x1);
            // A shift-click, not a sweep: nothing to zoom to.
            if (hi - lo < 6 || !onZoomRange) return;
            onZoomRange(startOfDay(dateAtX(lo)), startOfDay(dateAtX(hi)));
            return;
        }
        if (drag.kind === 'rows') {
            const moved = drag.hashes
                .map(h => model.tasks.find(x => x.hash === h))
                .filter((x): x is GanttTask => !!x);
            setDrag(null);
            if (moved.length > 0 && onReorderRows) onReorderRows(moved, drag.lane, drag.index);
            return;
        }
        const t = model.tasks.find(x => x.hash === drag.hash);
        setDrag(null);
        if (!t) return;
        if (drag.kind === 'move') {
            const shift = daysFromPx(drag.dx);
            if (shift !== 0 && onMove) {
                onMove(t, new Date(startOfDay(t.start).getTime() + shift * DAY_MS));
            }
        } else if (drag.kind === 'resize') {
            const base = t.plannedDays ?? t.days ?? 1;
            const next = Math.max(0.5, base + daysFromPx(drag.dx));
            if (next !== base && onResize) onResize(t, next);
        } else if (drag.kind === 'link') {
            const onto = drag.overHash ? model.tasks.find(x => x.hash === drag.overHash) : null;
            // A handle on the right says "this one comes first", a handle on the
            // left says "this one comes after", so which of the two ends up
            // waiting depends on the end the line was drawn from.
            if (onto && onto.hash !== t.hash && !onto.implied && onLink) {
                if (drag.side === 'right') onLink(onto, t);
                else onLink(t, onto);
            }
        }
    };

    // Where a bar is being shown right now, which is not where it is until the
    // drag has been let go of and the write has come back.
    const ghost = (t: GanttTask): { x: number; w: number } => {
        const bx = px(t.start);
        const bw = Math.max(px(t.end) - bx, 2);
        if (!drag || drag.kind === 'rows' || drag.kind === 'zoom' || drag.hash !== t.hash) return { x: bx, w: bw };
        if (drag.kind === 'move') return { x: bx + daysFromPx(drag.dx) * dayWidth, w: bw };
        if (drag.kind === 'resize') return { x: bx, w: Math.max(dayWidth / 2, bw + daysFromPx(drag.dx) * dayWidth) };
        return { x: bx, w: bw };
    };

    // --- dependency arrows -------------------------------------------------

    const arrows: { from: Placed; to: Placed; fromT: GanttTask; toT: GanttTask }[] = [];
    for (const t of model.tasks) {
        if (!t.hash || t.mark) continue;
        for (const depId of t.after) {
            const dep = model.tasks.find(x => x.id === depId);
            if (!dep || dep.mark) continue;
            const a = rowOf.get(dep.hash || dep.id);
            const b = rowOf.get(t.hash || t.id);
            if (a && b) arrows.push({ from: a, to: b, fromT: dep, toT: t });
        }
    }

    const arrowPath = (fromT: GanttTask, from: Placed, toT: GanttTask, to: Placed): string => {
        const x1 = px(fromT.end);
        const y1 = from.y + from.h / 2;
        const x2 = px(toT.start);
        const y2 = to.y + to.h / 2;
        // Out of the back of one bar, along the gap, into the front of the next.
        // When the next bar starts before this one ends the elbow goes round it
        // rather than backwards through both.
        const gap = 10;
        if (x2 - x1 > gap * 2) {
            const mx = x1 + Math.min(gap, (x2 - x1) / 2);
            return `M${x1},${y1} H${mx} V${y2} H${x2}`;
        }
        const below = y2 > y1 ? 1 : -1;
        const oy = y1 + (from.h / 2 + 4) * below;
        return `M${x1},${y1} H${x1 + gap} V${oy} H${x2 - gap} V${y2} H${x2}`;
    };

    return (
        <>
            {/* The dates, kept at the top of the viewport while the rows scroll
                under them. It is a separate svg in the same scrolling box, so
                it travels sideways with the body for free and only has to be
                pinned vertically - which is also why the body's rows now start
                at zero rather than below a header they no longer carry. */}
            <div
                style={{
                    position: 'sticky',
                    top: 0,
                    zIndex: 3,
                    background: colors.background,
                    width,
                }}
            >
                <svg
                    width={width}
                    height={headHeight}
                    viewBox={`0 0 ${width} ${headHeight}`}
                    role="presentation"
                    style={{ display: 'block', fontFamily: 'inherit', userSelect: 'none' }}
                >
                    <rect x={0} y={0} width={width} height={headHeight} fill={colors.background} />
                    {ticks.map((t, i) => (
                        <g key={`ht${i}`}>
                            <line
                                x1={px(t.d)} y1={headHeight - 8} x2={px(t.d)} y2={headHeight}
                                stroke={hair(t.major ? 0.26 : 0.1)}
                            />
                            <text
                                x={px(t.d) + 3} y={headHeight - 12} fill={ink}
                                fontFamily={TYPE.axis.family} fontSize={TYPE.axis.size}
                                fontWeight={t.major ? 600 : TYPE.axis.weight}
                                letterSpacing={TYPE.axis.spacing}
                                style={{ fontVariantNumeric: NUMERIC }}
                                opacity={t.major ? 0.85 : 0.5}
                            >
                                {t.label}
                            </text>
                        </g>
                    ))}
                    {dayWidth >= 18 && ticks.filter(t => t.d.getDate() === 1 || t === ticks[0]).map((t, i) => (
                        <text
                            key={`hm${i}`} x={px(t.d) + 3} y={headHeight - 26} fill={ink}
                            fontFamily={TYPE.axisMajor.family} fontSize={TYPE.axisMajor.size}
                            fontWeight={TYPE.axisMajor.weight} letterSpacing={TYPE.axisMajor.spacing}
                            style={{ fontVariantNumeric: NUMERIC }} opacity={0.75}
                        >
                            {MONTHS[t.d.getMonth()]} {t.d.getFullYear()}
                        </text>
                    ))}
                    {todayX !== null && (
                        <>
                            <line x1={todayX} y1={headHeight - 12} x2={todayX} y2={headHeight}
                                stroke={TODAY_COLOR} strokeWidth={1.5} />
                            <text
                                x={todayX + 4} y={headHeight - 15} fill={TODAY_COLOR}
                                fontFamily={TYPE.note.family} fontSize={TYPE.note.size}
                                fontWeight={TYPE.note.weight} letterSpacing="0.1em"
                            >
                                TODAY
                            </text>
                        </>
                    )}
                    {placedMarkers.map(({ m, mx, lane, shaped, color }, i) => (
                        <g key={`hmk${i}`}>
                            <title>{`${m.name}\n${dayKey(m.date)}${m.end ? ` → ${dayKey(new Date(m.end.getTime() - 1))}` : ''}`}</title>
                            {m.end && (
                                <rect x={mx} y={lane === 0 ? 6 : 19} width={Math.max(px(m.end) - mx, 1)}
                                    height={headHeight - (lane === 0 ? 6 : 19)} fill={color} opacity={0.1} />
                            )}
                            <line x1={mx} y1={lane === 0 ? 6 : 19} x2={mx} y2={headHeight}
                                stroke={color} strokeWidth={look.width} strokeDasharray={dash} />
                            {/* The shape is ringed in the chart's own ground so
                                it reads as a mark on the line, not a blot. */}
                            {shaped && (
                                <path d={shapePath(m.shape!, mx, lane === 0 ? 11 : 24, 5.5)}
                                    fill={color} stroke={colors.background} strokeWidth={1.5} />
                            )}
                            <text
                                x={mx + (shaped ? 9 : 4)} y={lane === 0 ? 15 : 28} fill={color}
                                fontFamily={TYPE.note.family} fontSize={TYPE.note.size}
                                fontWeight={TYPE.note.weight} letterSpacing={TYPE.note.spacing}
                            >
                                {m.name}
                            </text>
                        </g>
                    ))}
                    {/* The title, drawn after the marker labels so one
                        scrolled under it disappears rather than overprinting. */}
                    <g ref={titleRef}>
                        <rect x={0} y={0} width={LABEL_WIDTH + PAD} height={headHeight - 1} fill={colors.background} />
                        <text
                            x={PAD} y={23} fill={ink}
                            fontFamily={TYPE.title.family} fontSize={TYPE.title.size}
                            fontWeight={TYPE.title.weight} letterSpacing={TYPE.title.spacing}
                        >
                            {title}
                        </text>
                    </g>
                    <line
                        x1={0} y1={headHeight - 0.5} x2={width} y2={headHeight - 0.5}
                        stroke={hair(0.32)}
                    />
                </svg>
            </div>

        <svg
            ref={svgRef}
            width={width}
            height={height}
            viewBox={`0 0 ${width} ${height}`}
            role="img"
            aria-label={`Gantt chart: ${title}`}
            style={{ display: 'block', fontFamily: 'inherit', touchAction: 'none', userSelect: 'none' }}
            onPointerDown={beginZoom}
            onPointerMove={onPointerMove}
            onPointerUp={endDrag}
            onPointerLeave={() => setDrag(null)}
        >
            <defs>
                {barColors.map(c => (
                    <linearGradient key={c} id={barGradientId('rg', c)} x1="0" y1="0" x2="0" y2="1">
                        {barGradientStops(c).map(([off, stop]) => (
                            <stop key={off} offset={`${off}%`} stopColor={stop} />
                        ))}
                    </linearGradient>
                ))}
                <marker id="rg-arrow" markerWidth="7" markerHeight="7" refX="6" refY="3.5" orient="auto">
                    <path d="M0,0 L7,3.5 L0,7 z" fill={hair(0.5)} />
                </marker>
                <marker id="rg-arrow-crit" markerWidth="7" markerHeight="7" refX="6" refY="3.5" orient="auto">
                    <path d="M0,0 L7,3.5 L0,7 z" fill={colors.taskCrit} />
                </marker>
                {/* The fills the bar rules asked for, one per fill and colour
                    actually in use, as the gradients are. */}
                {patterns.map(({ fill, color }) => {
                    const id = patternId(fill, color);
                    const wash = washOf(color);
                    switch (fill) {
                        case 'hatched':
                            return (
                                <pattern key={id} id={id} width="6" height="6" patternTransform="rotate(45)" patternUnits="userSpaceOnUse">
                                    <rect width="6" height="6" fill={wash} />
                                    <line x1="1.5" y1="0" x2="1.5" y2="6" stroke={color} strokeWidth="3" />
                                </pattern>
                            );
                        case 'crosshatch':
                            return (
                                <pattern key={id} id={id} width="6" height="6" patternTransform="rotate(45)" patternUnits="userSpaceOnUse">
                                    <rect width="6" height="6" fill={wash} />
                                    <line x1="1" y1="0" x2="1" y2="6" stroke={color} strokeWidth="1.6" />
                                    <line x1="0" y1="1" x2="6" y2="1" stroke={color} strokeWidth="1.6" />
                                </pattern>
                            );
                        case 'dotted':
                            return (
                                <pattern key={id} id={id} width="5" height="5" patternUnits="userSpaceOnUse">
                                    <rect width="5" height="5" fill={wash} />
                                    <circle cx="2.5" cy="2.5" r="1.35" fill={color} />
                                </pattern>
                            );
                        case 'striped':
                            return (
                                <pattern key={id} id={id} width="6" height="6" patternUnits="userSpaceOnUse">
                                    <rect width="6" height="6" fill={wash} />
                                    <rect x="0" y="0" width="3" height="6" fill={color} />
                                </pattern>
                            );
                    }
                    return null;
                })}
                <pattern id="rg-implied" width="6" height="6" patternTransform="rotate(45)" patternUnits="userSpaceOnUse">
                    <rect width="6" height="6" fill={colors.background} />
                    <line x1="0" y1="0" x2="0" y2="6" stroke={hair(0.3)} strokeWidth="3" />
                </pattern>
            </defs>

            <rect x={0} y={0} width={width} height={height} fill={colors.background} />

            {shaded.map(d => (
                <rect key={`x${dayKey(d)}`} x={px(d)} y={plotTop} width={dayWidth} height={plotBottom - plotTop}
                    fill={hair(0.055)} />
            ))}

            {placed.filter(p => p.row.kind === 'section').map((p, i) => (
                <rect key={`s${i}`} x={PAD} y={p.y} width={width - PAD * 2} height={p.h} fill={colors.sectionAlt} />
            ))}

            {ticks.map((t, i) => (
                <line key={`t${i}`} x1={px(t.d)} y1={plotTop} x2={px(t.d)} y2={plotBottom}
                    stroke={hair(t.major ? 0.26 : 0.1)} />
            ))}

            {marks.map((t, i) => {
                const mx = px(t.start);
                const flip = width - PAD - mx < textWidth(t.name, 10) + 8;
                return (
                    <g key={`v${i}`}>
                        <line x1={mx} y1={plotTop} x2={mx} y2={plotBottom}
                            stroke={colors.taskCrit} strokeWidth={1.5} strokeDasharray="4 3" />
                        <text
                            x={mx + (flip ? -4 : 4)} y={plotTop + 12} textAnchor={flip ? 'end' : 'start'}
                            fill={colors.taskCrit} fontFamily={TYPE.note.family}
                            fontSize={TYPE.note.size} fontWeight={TYPE.note.weight}
                            letterSpacing={TYPE.note.spacing}
                        >
                            {t.name}
                        </text>
                    </g>
                );
            })}

            {todayX !== null && (
                <g>
                    <line x1={todayX} y1={plotTop} x2={todayX} y2={plotBottom} stroke={TODAY_COLOR} strokeWidth={1.5} />
                </g>
            )}

            {/* The markers. No pointer events: they cross every row, and a
                line that took clicks would make the bars under it undraggable. */}
            {placedMarkers.map(({ m, mx, mx2, color }, i) => (
                <g key={`mk${i}`} style={{ pointerEvents: 'none' }}>
                    {/* A range is a band, edged at both ends in the
                        marker's own line so it reads as one of the markers. */}
                    {m.end && (
                        <rect x={mx} y={plotTop} width={Math.max(mx2 - mx, 1)} height={plotBottom - plotTop}
                            fill={color} opacity={0.1} />
                    )}
                    <line x1={mx} y1={plotTop} x2={mx} y2={plotBottom}
                        stroke={color} strokeWidth={look.width} strokeDasharray={dash} opacity={0.85} />
                    {m.end && (
                        <line x1={mx2} y1={plotTop} x2={mx2} y2={plotBottom}
                            stroke={color} strokeWidth={look.width} strokeDasharray={dash} opacity={0.85} />
                    )}
                </g>
            ))}

            {/* Dependencies, under the bars so an arrow never hides one */}
            {arrows.map((a, i) => {
                const crit = !!critical && critical.has(a.fromT.id) && critical.has(a.toT.id);
                return (
                    <path key={`a${i}`} d={arrowPath(a.fromT, a.from, a.toT, a.to)}
                        fill="none" stroke={crit ? colors.taskCrit : hair(0.42)} strokeWidth={crit ? 2 : 1.2}
                        markerEnd={crit ? 'url(#rg-arrow-crit)' : 'url(#rg-arrow)'} />
                );
            })}

            {placed.map((p, i) => {
                if (p.row.kind === 'section') {
                    const row = p.row;
                    const cy = p.y + (row.shut ? SECTION_HEIGHT : p.h) / 2;
                    // The chevron: right when the lane is shut, down when it is
                    // open, which is the way every outline in the app turns.
                    const chev = row.shut
                        ? `M${PAD + 7},${cy - 4} L${PAD + 12},${cy} L${PAD + 7},${cy + 4} z`
                        : `M${PAD + 5},${cy - 2} L${PAD + 13},${cy - 2} L${PAD + 9},${cy + 3} z`;
                    const roll = row.rollup;
                    return (
                        <g
                            key={`sl${i}`}
                            onClick={() => onToggleLane && onToggleLane(row.name)}
                            style={{ cursor: onToggleLane ? 'pointer' : 'default' }}
                        >
                            <title>{row.shut ? `Open ${row.name}` : `Shut ${row.name}`}</title>
                            {/* The whole band is the hit target, not the little
                                triangle: a lane name is a big easy thing to aim
                                at and a chevron is not. */}
                            <rect x={PAD} y={p.y} width={width - PAD * 2} height={p.h} fill="transparent" />
                            {roll && (
                                <>
                                    {/* The roll-up: a slim bracket over the span
                                        the shut lane covers. Slim and hollow on
                                        purpose - it is a summary of bars, and
                                        drawing it like one more bar would have it
                                        read as a task nobody can find. */}
                                    <rect
                                        x={px(roll.start)} y={cy - 3}
                                        width={Math.max(px(roll.end) - px(roll.start), 3)} height={6} rx={2}
                                        fill={laneInk} opacity={0.34}
                                    />
                                    <rect x={px(roll.start)} y={cy - 6} width={2} height={12} fill={laneInk} opacity={0.5} />
                                    <rect x={px(roll.end) - 2} y={cy - 6} width={2} height={12} fill={laneInk} opacity={0.5} />
                                    {/* How long the lane runs, knocked out of the
                                        middle of its own beam - the patch of
                                        chart behind it is what breaks the line
                                        around the number instead of letting it
                                        strike through. Only when there is room:
                                        a number wider than the span it measures
                                        is worse than no number. */}
                                    {(() => {
                                        const x1 = px(roll.start);
                                        const x2 = px(roll.end);
                                        const days = daySpan(roll.start, roll.end);
                                        const text = `${days}d`;
                                        const w = textWidth(text, 10) + 10;
                                        if (x2 - x1 < w + 16) return null;
                                        const mid = (x1 + x2) / 2;
                                        return (
                                            <>
                                                <rect
                                                    x={mid - w / 2} y={cy - 6} width={w} height={12}
                                                    fill={colors.sectionAlt}
                                                />
                                                <text
                                                    x={mid} y={cy + 3} textAnchor="middle" fill={laneInk}
                                                    fontFamily={TYPE.axis.family} fontSize={10}
                                                    fontWeight={600} letterSpacing="0.08em"
                                                    style={{ fontVariantNumeric: NUMERIC }} opacity={0.7}
                                                >
                                                    {text}
                                                </text>
                                            </>
                                        );
                                    })()}
                                </>
                            )}
                        </g>
                    );
                }
                const t = p.row.task;
                const cy = p.y + ROW_HEIGHT / 2;
                const g = ghost(t);
                const fill = barColor(t);
                // How the rules say this bar is drawn. An outline replaces the
                // hairline and stays through selection - the row band already
                // says selected.
                const st = styleFor(t);
                const ring = st.outline;
                const symbol = isSymbolShape(st.shape);
                const hollow = st.fill === 'hollow';
                const patterned = st.fill !== 'solid' && !hollow;
                const label = t.name;
                // A hatched bar - one the query did not find, pulled in because
                // something waits on it - is painted half in the chart's own
                // background and half in a veil of ink, so *no* single colour
                // reads on all of it: in dark mode the label came out black on
                // black. Its name goes on the page beside the bar instead,
                // where the ground is one known colour. A bar drawn as a symbol
                // has no inside to put a name in either.
                const inside = !t.milestone && !t.implied && !symbol && g.w > textWidth(label, 11) + 16;
                const dragging = drag && drag.kind === 'rows' && t.hash
                    ? drag.hashes.indexOf(t.hash) >= 0
                    : false;
                const on = hover === t.id
                    || (drag && (drag.kind === 'move' || drag.kind === 'resize' || drag.kind === 'link') && drag.hash === t.hash)
                    || dragging;
                const isCrit = !!critical && critical.has(t.id);
                const health = healthOf ? healthOf(t) : null;
                const base = baselineOf ? baselineOf(t) : null;
                const isSel = !!selected && selected === t.hash;
                const isPicked = !!t.hash && chosen.has(t.hash);
                const pct = Math.max(0, Math.min(100, t.percent || 0));
                const dragTarget = drag?.kind === 'link' && drag.overHash === t.hash;
                const top = cy - BAR_HEIGHT / 2;
                // The edge every shape is drawn with: the rule's outline, or
                // for a hollow bar its own colour (a hollow bar *is* its
                // edge), or the usual hairline of the bar's own shadow.
                const edge = ring ? ring.color : hollow ? fill : isSel ? ink : shade(fill, -0.22);
                const edgeOpacity = ring || hollow ? 1 : isSel ? 0.9 : 0.55;
                const edgeWidth = ring ? ring.width + (isSel ? 0.5 : 0) : hollow ? 1.75 : isSel ? 1.5 : 1;
                const startMove = (e: React.PointerEvent) =>
                    !t.implied && beginDrag(e, { kind: 'move', hash: t.hash || '', fromX: at(e).x, dx: 0 });
                // The span's outline, which is also what the done part is
                // clipped to, so a pill or a wave is filled in its own shape.
                const outlinePath = st.shape === 'wavy'
                    ? wavyBarPath(g.x, top, g.w, BAR_HEIGHT)
                    : null;
                const rx = st.shape === 'pill' ? BAR_HEIGHT / 2 : 4;
                const symR = st.shape === 'circle' ? 7.5 : 8.5;
                const clipId = `rgc${i}`;
                return (
                    <g key={`r${i}`}
                        onMouseEnter={() => setHover(t.id)}
                        onMouseLeave={() => setHover('')}
                        onClick={() => onSelect && onSelect(t)}
                        onContextMenu={e => {
                            if (!onBarMenu || t.implied) return;
                            e.preventDefault();
                            onBarMenu(t, e.clientX, e.clientY);
                        }}
                        style={{ cursor: 'pointer' }}
                    >
                        <title>{tipFor(t) + (health ? `\n${health.note}` : '')
                            + (base ? `\nbaseline ${dayKey(base.start)} → ${dayKey(new Date(base.end.getTime() - 1))}` : '')}</title>
                        {/* Trouble tints the whole row faintly, so it can be
                            found from across the chart; the words beside the
                            bar say which trouble. */}
                        {health && (
                            <rect x={PAD} y={p.y} width={width - PAD * 2} height={p.h}
                                fill={HEALTH_COLOR[health.kind]} opacity={0.07} />
                        )}
                        {/* Where the baseline had it: a slim ghost under the
                            bar, so the difference is the gap between them. */}
                        {base && !t.milestone && (
                            <rect x={px(base.start)} y={top + BAR_HEIGHT + 1}
                                width={Math.max(px(base.end) - px(base.start), 2)} height={3.5} rx={1.75}
                                fill={ink} opacity={0.32} style={{ pointerEvents: 'none' }} />
                        )}
                        {/* The critical path: a halo round the bar rather than
                            a colour or an outline, both of which the rules may
                            already be using to say something else. */}
                        {isCrit && !t.milestone && (
                            symbol ? (
                                <circle cx={g.x} cy={cy} r={symR + 3.5} fill={colors.taskCrit} opacity={0.35}
                                    style={{ pointerEvents: 'none' }} />
                            ) : (
                                <rect x={g.x - 3} y={top - 3} width={g.w + 6} height={BAR_HEIGHT + 6} rx={rx + 3}
                                    fill={colors.taskCrit} opacity={0.3} style={{ pointerEvents: 'none' }} />
                            )
                        )}
                        {(on || isSel || isPicked || dragTarget) && (
                            <rect x={PAD} y={p.y} width={width - PAD * 2} height={p.h}
                                fill={isPicked || isSel ? colors.taskActive : hair(1)}
                                opacity={isPicked ? 0.18 : isSel ? 0.14 : dragTarget ? 0.12 : 0.05}
                                data-transient="1" />
                        )}
                        {t.milestone ? (
                            <polygon
                                points={`${g.x},${cy - 8} ${g.x + 8},${cy} ${g.x},${cy + 8} ${g.x - 8},${cy}`}
                                fill={fillOf(t)}
                                stroke={ring ? ring.color : isSel ? ink : shade(fill, -0.18)}
                                strokeOpacity={ring ? 1 : 0.7} strokeWidth={ring ? ring.width : 1}
                                onPointerDown={e => beginDrag(e, { kind: 'move', hash: t.hash || '', fromX: at(e).x, dx: 0 })}
                            />
                        ) : symbol ? (
                            <>
                                {/* A symbol on the start date, with a slim track
                                    to the end so the length still reads. The
                                    track is the bar's colour, the done part of
                                    it darker; both take the drag. */}
                                <rect x={g.x} y={cy - 2.5} width={g.w} height={5} rx={2.5}
                                    fill={fill} opacity={0.45}
                                    style={{ cursor: readOnly || t.implied ? 'pointer' : 'grab' }}
                                    onPointerDown={startMove} />
                                {pct > 0 && (
                                    <rect x={g.x} y={cy - 2.5} width={g.w * pct / 100} height={5} rx={2.5}
                                        fill={fill} opacity={0.9} style={{ pointerEvents: 'none' }} />
                                )}
                                <rect x={g.x + g.w - 2} y={cy - 6} width={2} height={12} fill={fill} opacity={0.75}
                                    style={{ pointerEvents: 'none' }} />
                                <path
                                    d={shapePath(st.shape as 'diamond' | 'circle' | 'star', g.x, cy, symR)}
                                    fill={fillOf(t)} stroke={edge} strokeOpacity={edgeOpacity}
                                    strokeWidth={edgeWidth} strokeLinejoin="round"
                                    style={{ cursor: readOnly || t.implied ? 'pointer' : 'grab' }}
                                    onPointerDown={startMove}
                                />
                            </>
                        ) : (
                            <>
                                {outlinePath ? (
                                    <>
                                        <clipPath id={clipId}><path d={outlinePath} /></clipPath>
                                        <path
                                            d={outlinePath}
                                            fill={fillOf(t)} stroke={edge} strokeOpacity={edgeOpacity}
                                            strokeWidth={edgeWidth} opacity={t.implied ? 0.8 : 1}
                                            style={{ cursor: readOnly || t.implied ? 'pointer' : 'grab' }}
                                            onPointerDown={startMove}
                                        />
                                    </>
                                ) : (
                                    <>
                                        <clipPath id={clipId}>
                                            <rect x={g.x} y={top} width={g.w} height={BAR_HEIGHT} rx={rx} />
                                        </clipPath>
                                        <rect
                                            x={g.x} y={top} width={g.w} height={BAR_HEIGHT} rx={rx}
                                            fill={fillOf(t)} stroke={edge} strokeOpacity={edgeOpacity}
                                            strokeWidth={edgeWidth} opacity={t.implied ? 0.8 : 1}
                                            style={{ cursor: readOnly || t.implied ? 'pointer' : 'grab' }}
                                            onPointerDown={startMove}
                                        />
                                    </>
                                )}
                                {/* What is done of it, painted darker inside the
                                    bar and clipped to the bar's own shape. On a
                                    hollow bar the done part is filled in with
                                    the colour, which is what done looks like
                                    on something drawn as an outline. */}
                                {pct > 0 && (
                                    <rect x={g.x} y={top} width={g.w * pct / 100} height={BAR_HEIGHT}
                                        clipPath={`url(#${clipId})`}
                                        fill={hollow ? fill : '#000000'} opacity={hollow ? 0.35 : 0.2}
                                        style={{ pointerEvents: 'none' }} />
                                )}
                                {/* The grip that changes the effort */}
                                {!readOnly && !t.implied && (on || isSel) && (
                                    <rect x={g.x + g.w - GRIP} y={top} width={GRIP} height={BAR_HEIGHT}
                                        fill={contrastText(fill)} opacity={0.22} style={{ cursor: 'ew-resize' }} data-transient="1"
                                        onPointerDown={e => beginDrag(e, { kind: 'resize', hash: t.hash || '', fromX: at(e).x, dx: 0 })} />
                                )}
                            </>
                        )}
                        {/* The grip on a symbol's track, at its end. */}
                        {symbol && !t.milestone && !readOnly && !t.implied && (on || isSel) && (
                            <rect x={g.x + g.w - GRIP} y={top} width={GRIP} height={BAR_HEIGHT}
                                fill={ink} opacity={0.12} style={{ cursor: 'ew-resize' }} data-transient="1"
                                onPointerDown={e => beginDrag(e, { kind: 'resize', hash: t.hash || '', fromX: at(e).x, dx: 0 })} />
                        )}
                        {/* The handles a dependency is dragged from, one at each
                            end: off the right to say what follows this task,
                            off the left to say what it waits for. Both sit
                            outside the bar so neither is over the grip that
                            changes the estimate - or, for a symbol, over the
                            symbol itself. */}
                        {!t.milestone && !readOnly && !t.implied && (on || isSel) && (
                            <>
                                <circle data-transient="1" cx={g.x - (symbol ? symR + 7 : 7)} cy={cy} r={4.5}
                                    fill={colors.background} stroke={ink} strokeOpacity={0.6}
                                    style={{ cursor: 'crosshair' }}
                                    onPointerDown={e => beginDrag(e, { kind: 'link', hash: t.hash || '', side: 'left', x: at(e).x, y: at(e).y, overHash: '' })}>
                                    <title>{`Drag onto the task ${t.name} waits for`}</title>
                                </circle>
                                <circle data-transient="1" cx={g.x + g.w + 7} cy={cy} r={4.5}
                                    fill={colors.background} stroke={ink} strokeOpacity={0.6}
                                    style={{ cursor: 'crosshair' }}
                                    onPointerDown={e => beginDrag(e, { kind: 'link', hash: t.hash || '', side: 'right', x: at(e).x, y: at(e).y, overHash: '' })}>
                                    <title>{`Drag onto the task that follows ${t.name}`}</title>
                                </circle>
                            </>
                        )}
                        {!t.milestone && (
                            inside ? (
                                <>
                                    {/* On a pattern no single ink reads, so the
                                        name sits on a chip of the bar's own
                                        colour. On a hollow bar the inside is
                                        the chart's ground and needs none. */}
                                    {patterned && (
                                        <rect
                                            x={g.x + 4} y={cy - 7} width={textWidth(label, 11) + 8} height={14} rx={3}
                                            fill={fill} style={{ pointerEvents: 'none' }}
                                        />
                                    )}
                                    <text
                                        x={g.x + 8} y={cy + 4} fill={hollow ? ink : contrastText(fill)}
                                        fontFamily={TYPE.barLabel.family} fontSize={TYPE.barLabel.size}
                                        fontWeight={TYPE.barLabel.weight} letterSpacing={TYPE.barLabel.spacing}
                                        style={{ pointerEvents: 'none' }}
                                    >
                                        {label}
                                    </text>
                                </>
                            ) : (
                                <text
                                    x={g.x + g.w + (readOnly ? 5 : 16)} y={cy + 4} fill={ink}
                                    fontFamily={TYPE.barLabel.family} fontSize={TYPE.barLabel.size}
                                    fontWeight={TYPE.barLabel.weight} letterSpacing={TYPE.barLabel.spacing}
                                    style={{ pointerEvents: 'none', fontVariantNumeric: NUMERIC }}
                                    opacity={t.implied ? 0.75 : 0.6}
                                >
                                    {t.implied
                                        ? label
                                        : `${fmtDays(t.plannedDays !== null ? t.plannedDays : t.days)}d`}
                                </text>
                            )
                        )}
                        {health && (
                            <text
                                x={g.x + g.w + (readOnly ? 5 : 16)
                                    + (inside || t.milestone ? 0 : textWidth(`${fmtDays(t.plannedDays !== null ? t.plannedDays : t.days)}d`, 11) + 8)}
                                y={cy + 4} fill={HEALTH_COLOR[health.kind]}
                                fontFamily={TYPE.barLabel.family} fontSize={TYPE.barLabel.size}
                                fontWeight={700} letterSpacing={TYPE.barLabel.spacing}
                                style={{ pointerEvents: 'none' }}
                            >
                                {health.note}
                            </text>
                        )}
                    </g>
                );
            })}

            {/* The names, pinned. Drawn last so they sit over the bars, on an
                opaque strip of the chart's own ground so a bar scrolling under
                them disappears cleanly rather than showing through. Each row
                repaints its own band here, because the strip would otherwise
                cover the lane shading and the hover highlight that the
                scrolling layer draws full width. */}
            <g ref={namesRef}>
                <rect x={0} y={0} width={LABEL_WIDTH + PAD} height={height} fill={colors.background} />
                {placed.map((p, i) => {
                    const cy = p.y + (p.row.kind === 'section' ? SECTION_HEIGHT : ROW_HEIGHT) / 2;
                    if (p.row.kind === 'section') {
                        const row = p.row;
                        const chev = row.shut
                            ? `M${PAD + 7},${cy - 4} L${PAD + 12},${cy} L${PAD + 7},${cy + 4} z`
                            : `M${PAD + 5},${cy - 2} L${PAD + 13},${cy - 2} L${PAD + 9},${cy + 3} z`;
                        return (
                            <g
                                key={`nn${i}`}
                                onClick={() => onToggleLane && onToggleLane(row.name)}
                                style={{ cursor: onToggleLane ? 'pointer' : 'default' }}
                            >
                                <title>{row.shut ? `Open ${row.name}` : `Shut ${row.name}`}</title>
                                <rect x={PAD} y={p.y} width={LABEL_WIDTH} height={p.h} fill={colors.sectionAlt} />
                                <path d={chev} fill={laneInk} opacity={0.6} />
                                <text
                                    x={PAD + 19} y={cy + 4} fill={laneInk}
                                    fontFamily={TYPE.lane.family} fontSize={TYPE.lane.size}
                                    fontWeight={TYPE.lane.weight} letterSpacing={TYPE.lane.spacing}
                                    opacity={0.72}
                                >
                                    {row.name.toUpperCase()}
                                </text>
                                {row.rollup && (
                                    <text
                                        x={LABEL_WIDTH - 2} y={cy + 4} textAnchor="end" fill={laneInk}
                                        fontFamily={TYPE.axis.family} fontSize={TYPE.axis.size}
                                        fontWeight={TYPE.axis.weight} letterSpacing={TYPE.axis.spacing}
                                        style={{ fontVariantNumeric: NUMERIC }} opacity={0.6}
                                    >
                                        {`${row.rollup.count} task${row.rollup.count === 1 ? '' : 's'}`}
                                    </text>
                                )}
                            </g>
                        );
                    }
                    const t = p.row.task;
                    const isPicked = !!t.hash && chosen.has(t.hash);
                    const isSel = !!selected && selected === t.hash;
                    const on = hover === t.id;
                    const dragging = drag && drag.kind === 'rows' && t.hash
                        ? drag.hashes.indexOf(t.hash) >= 0
                        : false;
                    const label = t.name;
                    return (
                        <g
                            key={`nr${i}`}
                            onMouseEnter={() => setHover(t.id)}
                            onMouseLeave={() => setHover('')}
                            onClick={() => onSelect && onSelect(t)}
                            style={{ cursor: 'pointer' }}
                        >
                            <title>{tipFor(t)}</title>
                            {(on || isSel || isPicked) && (
                                <rect x={PAD} y={p.y} width={LABEL_WIDTH} height={p.h}
                                    fill={isPicked || isSel ? colors.taskActive : hair(1)}
                                    opacity={isPicked ? 0.18 : isSel ? 0.14 : 0.05}
                                    data-transient="1" />
                            )}
                            {grippable(t) && (
                                <g data-transient="1" onPointerDown={e => beginRowDrag(e, t)} style={{ cursor: 'grab' }}>
                                    <title>{`Drag to reorder${chosen.size > 1 && isPicked ? ` (${chosen.size} rows)` : ''} - shift or ${MOD} to pick more`}</title>
                                    <rect x={PAD} y={p.y} width={GRIP_W} height={p.h} fill="transparent" />
                                    {[0, 1, 2].map(k => (
                                        <rect
                                            key={k}
                                            x={PAD + 4} y={cy - 5 + k * 4} width={9} height={1.5} rx={0.75}
                                            fill={isPicked ? colors.taskActive : laneInk}
                                            opacity={isPicked ? 0.95 : on ? 0.5 : 0.22}
                                        />
                                    ))}
                                </g>
                            )}
                            <text
                                x={LABEL_WIDTH - 2} y={cy + 4} textAnchor="end"
                                fill={ink}
                                fontFamily={TYPE.task.family} fontSize={TYPE.task.size}
                                fontWeight={isSel || isPicked ? 600 : TYPE.task.weight}
                                letterSpacing={TYPE.task.spacing}
                                opacity={dragging ? 0.45 : t.implied ? 0.5 : t.state === 'done' ? 0.6 : 0.92}
                            >
                                {label.length > 30 ? label.slice(0, 29) + '…' : label}
                            </text>
                        </g>
                    );
                })}
            </g>

            {/* Where the rows being dragged would land: a line between the two
                rows they would sit between, drawn the full width so it is
                findable whichever part of the chart is being looked at. */}
            {drag?.kind === 'rows' && (() => {
                const rows = placed.filter(
                    p => p.row.kind === 'task' && (p.row as any).task.section === drag.lane,
                );
                let y: number;
                if (rows.length === 0) {
                    const head = placed.find(p => p.row.kind === 'section' && (p.row as any).name === drag.lane);
                    y = head ? head.y + head.h : plotTop;
                } else if (drag.index >= rows.length) {
                    const last = rows[rows.length - 1];
                    y = last.y + last.h;
                } else {
                    y = rows[drag.index].y;
                }
                return (
                    <g style={{ pointerEvents: 'none' }}>
                        <rect x={PAD} y={y - 1.5} width={width - PAD * 2} height={3} rx={1.5}
                            fill={colors.taskActive} opacity={0.9} />
                        <circle cx={PAD + 2} cy={y} r={3.5} fill={colors.taskActive} />
                        <text
                            x={PAD + GRIP_W + 4} y={y - 5} fill={colors.taskActive}
                            fontFamily={TYPE.note.family} fontSize={TYPE.note.size}
                            fontWeight={TYPE.note.weight} letterSpacing={TYPE.note.spacing}
                        >
                            {drag.hashes.length > 1 ? `${drag.hashes.length} rows` : ''}
                        </text>
                    </g>
                );
            })()}

            {/* The stretch being swept out to zoom to, with its dates. */}
            {drag?.kind === 'zoom' && Math.abs(drag.x1 - drag.x0) > 2 && (() => {
                const lo = Math.min(drag.x0, drag.x1);
                const hi = Math.max(drag.x0, drag.x1);
                const a = startOfDay(dateAtX(lo));
                const b = startOfDay(dateAtX(hi));
                return (
                    <g style={{ pointerEvents: 'none' }}>
                        <rect x={lo} y={0} width={hi - lo} height={height}
                            fill={colors.taskActive} opacity={0.12} />
                        <rect x={lo} y={0} width={hi - lo} height={height}
                            fill="none" stroke={colors.taskActive} strokeWidth={1.5} strokeDasharray="5 3" />
                        <text x={lo + 6} y={14} fill={colors.taskActive}
                            fontFamily={TYPE.note.family} fontSize={TYPE.note.size}
                            fontWeight={700} letterSpacing={TYPE.note.spacing}
                            style={{ fontVariantNumeric: NUMERIC }}>
                            {`${fmtDay(a)} → ${fmtDay(b)} · ${daySpan(a, b)}d`}
                        </text>
                    </g>
                );
            })()}

            {/* The rubber band of a dependency being drawn */}
            {drag?.kind === 'link' && (() => {
                const t = model.tasks.find(x => x.hash === drag.hash);
                const p = t && t.hash ? rowOf.get(t.hash) : null;
                if (!t || !p) return null;
                const fromX = drag.side === 'left' ? px(t.start) - 7 : px(t.end) + 7;
                return (
                    <path
                        d={`M${fromX},${p.y + p.h / 2} L${drag.x},${drag.y}`}
                        stroke={colors.taskActive} strokeWidth={1.5} strokeDasharray="4 3" fill="none"
                        style={{ pointerEvents: 'none' }}
                    />
                );
            })()}

            {rows.length === 0 && (
                <text x={x0} y={plotTop + 30} fill={ink} fontFamily={TYPE.task.family} fontSize={13} opacity={0.7}>
                    Nothing to draw: the query found no dated tasks.
                </text>
            )}
        </svg>
        </>
    );
}
