import * as React from 'react';
import Box from '@mui/joy/Box';
import Sheet from '@mui/joy/Sheet';
import Typography from '@mui/joy/Typography';
import Input from '@mui/joy/Input';
import Button from '@mui/joy/Button';
import ButtonGroup from '@mui/joy/ButtonGroup';
import Select from '@mui/joy/Select';
import Option from '@mui/joy/Option';
import ListDivider from '@mui/joy/ListDivider';
import CircularProgress from '@mui/joy/CircularProgress';
import List from '@mui/joy/List';
import ListItem from '@mui/joy/ListItem';
import ListItemButton from '@mui/joy/ListItemButton';
import SaveIcon from '@mui/icons-material/Save';
import OpenInNewIcon from '@mui/icons-material/OpenInNew';
import SearchIcon from '@mui/icons-material/Search';
import InsertDriveFileIcon from '@mui/icons-material/InsertDriveFile';
import EditIcon from '@mui/icons-material/Edit';
import OrgEditor from './OrgEditor';
import { ODb } from '../db';

// The four presentation exporters, and the one thing each of them is asked
// about besides the file.
//
// A deck says what it wants in the org file - `#+REVEAL_THEME:`,
// `#+IMPRESS_LAYOUT:`, `#+DECK_TRANSITION:` - and these dropdowns are for
// trying another one against it without editing anything. Nothing is sent
// unless it was picked, so the file's own choice is what you get by default:
// "From the file" is not a theme, it is the absence of an override.
type PresentationMode = 'revealjs' | 'impressjs' | 'webslides' | 'deckjs';

type Framework = {
  mode: PresentationMode;
  label: string;
  // What this framework calls its look, and what it offers.
  styleLabel?: string;
  styles?: string[];
  // The second thing worth choosing: a motion, or a way of placing steps.
  motionLabel?: string;
  motions?: string[];
  // Which request parameter the motion is.
  motionKey?: 'layout' | 'transition';
  note: string;
};

const FRAMEWORKS: Framework[] = [
  {
    mode: 'revealjs',
    label: 'Reveal.js',
    styleLabel: 'Theme',
    styles: ['black', 'white', 'league', 'beige', 'sky', 'night', 'serif',
      'simple', 'solarized', 'blood', 'moon', 'dracula'],
    note: 'Slides, stacks and a speaker view. Press s while presenting for notes.',
  },
  {
    mode: 'impressjs',
    label: 'Impress.js',
    styleLabel: 'Theme',
    styles: ['impressdefault'],
    motionLabel: 'Layout',
    motions: ['rel', 'line', 'grid', 'spiral', 'ring', 'zoom', 'random', 'none'],
    motionKey: 'layout',
    note: 'Steps on an infinite canvas. A layout places them for you.',
  },
  {
    mode: 'webslides',
    label: 'WebSlides',
    styleLabel: 'Ground',
    styles: ['light', 'dark', 'white', 'black', 'apple', 'blue', 'primary', 'gradient'],
    note: 'A page that scrolls, and reads properly on a phone.',
  },
  {
    mode: 'deckjs',
    label: 'Deck.js',
    styleLabel: 'Theme',
    styles: ['web-2.0', 'swiss', 'neon'],
    motionLabel: 'Transition',
    motions: ['horizontal-slide', 'vertical-slide', 'fade'],
    motionKey: 'transition',
    note: 'Plain and old and dependable. A nested heading is a step.',
  },
];

const frameworkOf = (mode: PresentationMode): Framework =>
  FRAMEWORKS.find(f => f.mode === mode) || FRAMEWORKS[0];

function fuzzyMatch(pattern: string, str: string): boolean {
  const lower = str.toLowerCase();
  const pat = pattern.toLowerCase();
  let pi = 0;
  for (let i = 0; i < lower.length && pi < pat.length; i++) {
    if (lower[i] === pat[pi]) pi++;
  }
  return pi === pat.length;
}

export default function Presentation() {
  const [allFiles, setAllFiles] = React.useState<string[]>([]);
  const [searchText, setSearchText] = React.useState('');
  const [selectedFile, setSelectedFile] = React.useState<string | null>(null);
  const [showDropdown, setShowDropdown] = React.useState(false);
  const [mode, setMode] = React.useState<PresentationMode>('revealjs');
  const [style, setStyle] = React.useState<string>('');
  // The themes the server has, which work in all four frameworks. They are
  // offered above each framework's own, because one of them is nearly always
  // the better answer - and because a deck themed with one looks the same
  // whichever framework it is shown with.
  const [shared, setShared] = React.useState<string[]>([]);
  const [motion, setMotion] = React.useState<string>('');
  const [htmlContent, setHtmlContent] = React.useState<string>('');
  const [loading, setLoading] = React.useState(false);
  const [loadingFiles, setLoadingFiles] = React.useState(true);
  const [error, setError] = React.useState<string>('');
  const [editorOpen, setEditorOpen] = React.useState(false);
  const iframeRef = React.useRef<HTMLIFrameElement>(null);
  const dropdownRef = React.useRef<HTMLDivElement>(null);

  React.useEffect(() => {
    ODb.slideThemes().then(setShared).catch(() => setShared([]));
  }, []);

  React.useEffect(() => {
    ODb.getFiles().then(result => {
      setAllFiles(result || []);
      setLoadingFiles(false);
    }).catch(() => {
      setAllFiles([]);
      setLoadingFiles(false);
    });
  }, []);

  // Close dropdown on outside click
  React.useEffect(() => {
    const handleClick = (e: MouseEvent) => {
      if (dropdownRef.current && !dropdownRef.current.contains(e.target as Node)) {
        setShowDropdown(false);
      }
    };
    document.addEventListener('mousedown', handleClick);
    return () => document.removeEventListener('mousedown', handleClick);
  }, []);

  const filteredFiles = React.useMemo(() => {
    if (!searchText) return allFiles.slice(0, 20);
    return allFiles.filter(f => fuzzyMatch(searchText, f)).slice(0, 20);
  }, [searchText, allFiles]);

  const handleSelectFile = (file: string) => {
    setSelectedFile(file);
    setSearchText(file.split('/').pop() || file);
    setShowDropdown(false);
  };

  const fetchPresentation = React.useCallback(async (overrideMode?: PresentationMode) => {
    if (!selectedFile) return;

    const activeMode = overrideMode || mode;
    const fw = frameworkOf(activeMode);
    setLoading(true);
    setError('');
    setHtmlContent('');
    try {
      // The overrides go only when they were picked, and only when they mean
      // something to this framework - switching from impress to deck.js must
      // not send an impress layout as a deck.js transition.
      const result = await ODb.presentation(activeMode, selectedFile, {
        theme: fw.styles ? style : '',
        layout: fw.motionKey === 'layout' ? motion : '',
        transition: fw.motionKey === 'transition' ? motion : '',
      });

      let html = '';
      if (result && typeof result === 'object' && result.Msg) {
        html = result.Msg as string;
      } else if (result && typeof result === 'object' && result.Content) {
        html = result.Content;
      } else if (typeof result === 'string') {
        html = result;
      }
      if (html) {
        setHtmlContent(html);
      } else {
        setError('No presentation data found in server response');
      }
    } catch (e: any) {
      setError(e.message || 'Failed to fetch presentation');
    } finally {
      setLoading(false);
    }
  }, [selectedFile, mode, style, motion]);

  React.useEffect(() => {
    if (!htmlContent || !iframeRef.current) return;
    const doc = iframeRef.current.contentDocument;
    if (doc) {
      doc.open();
      doc.write(htmlContent);
      doc.close();
    }
  }, [htmlContent]);

  const handleModeToggle = (newMode: PresentationMode) => {
    if (newMode === mode) return;
    setMode(newMode);
    // A theme and a layout belong to the framework they were picked in:
    // 'solarized' means nothing to deck.js and 'spiral' means nothing to
    // anything else, so both go back to what the file says.
    setStyle('');
    setMotion('');
    if (htmlContent && selectedFile) {
      fetchPresentation(newMode);
    }
  };

  const active = frameworkOf(mode);

  const handleOpenInNewTab = () => {
    if (!htmlContent) return;
    const blob = new Blob([htmlContent], { type: 'text/html' });
    const url = URL.createObjectURL(blob);
    window.open(url, '_blank');
  };

  const handleSave = () => {
    if (!htmlContent) return;
    const title = selectedFile?.split('/').pop()?.replace(/\.org$/, '') || 'presentation';
    const blob = new Blob([htmlContent], { type: 'text/html' });
    const url = URL.createObjectURL(blob);
    const a = document.createElement('a');
    a.href = url;
    a.download = `${title.replace(/[^a-zA-Z0-9_-]/g, '_')}_${mode}.html`;
    a.click();
    URL.revokeObjectURL(url);
  };

  return (
    <Box sx={{ display: 'flex', flexDirection: 'column', gap: 2, height: '100%' }}>
      {/* Controls */}
      <Sheet variant="outlined" sx={{ borderRadius: 'sm', p: 2 }}>
        <Box sx={{ display: 'flex', alignItems: 'center', gap: 2, flexWrap: 'wrap' }}>
          <Typography level="title-sm" sx={{ minWidth: 'fit-content' }}>File:</Typography>
          {loadingFiles ? (
            <CircularProgress size="sm" />
          ) : allFiles.length === 0 ? (
            <Typography level="body-sm" sx={{ color: 'text.secondary' }}>
              No org files found.
            </Typography>
          ) : (
            <>
              {/* `minWidth` rather than `width`, and capped at the room there
                  is: 350px is a comfortable box on a laptop and 90px wider than
                  an iPhone's content column, where it pushed the whole page
                  sideways. */}
              <Box ref={dropdownRef} sx={{ position: 'relative', minWidth: 0, width: '100%', maxWidth: 350, flex: 1 }}>
                <Input
                  size="sm"
                  placeholder="Search for an org file..."
                  startDecorator={<SearchIcon />}
                  value={searchText}
                  onChange={(e) => {
                    setSearchText(e.target.value);
                    setSelectedFile(null);
                    setShowDropdown(true);
                  }}
                  onFocus={() => setShowDropdown(true)}
                  sx={{ width: '100%' }}
                />
                {showDropdown && filteredFiles.length > 0 && (
                  <Sheet
                    variant="outlined"
                    sx={{
                      position: 'absolute',
                      top: '100%',
                      left: 0,
                      right: 0,
                      zIndex: 1000,
                      maxHeight: 300,
                      overflow: 'auto',
                      borderRadius: 'sm',
                      mt: 0.5,
                    }}
                  >
                    <List size="sm">
                      {filteredFiles.map(f => (
                        <ListItem key={f}>
                          <ListItemButton onClick={() => handleSelectFile(f)}>
                            <InsertDriveFileIcon sx={{ fontSize: 16, mr: 1, color: 'text.tertiary' }} />
                            <Typography level="body-sm" sx={{ fontFamily: 'monospace', fontSize: '0.8rem' }}>
                              {f}
                            </Typography>
                          </ListItemButton>
                        </ListItem>
                      ))}
                    </List>
                  </Sheet>
                )}
              </Box>
              <ButtonGroup size="sm" variant="outlined">
                {FRAMEWORKS.map(f => (
                  <Button
                    key={f.mode}
                    color={mode === f.mode ? 'primary' : 'neutral'}
                    variant={mode === f.mode ? 'solid' : 'outlined'}
                    onClick={() => handleModeToggle(f.mode)}
                    title={f.note}
                  >
                    {f.label}
                  </Button>
                ))}
              </ButtonGroup>
              {(shared.length > 0 || (active.styles && active.styles.length > 1)) && (
                <Select
                  size="sm"
                  value={style}
                  placeholder={active.styleLabel}
                  onChange={(_, v) => setStyle((v as string) || '')}
                  sx={{ minWidth: 170 }}
                >
                  <Option value="">From the file</Option>
                  {shared.map(t => <Option key={'s-' + t} value={t}>{t}</Option>)}
                  {shared.length > 0 && active.styles && active.styles.length > 1 && (
                    <ListDivider />
                  )}
                  {(active.styles || []).map(t => (
                    <Option key={'f-' + t} value={t}>{t}</Option>
                  ))}
                </Select>
              )}
              {active.motions && (
                <Select
                  size="sm"
                  value={motion}
                  placeholder={active.motionLabel}
                  onChange={(_, v) => setMotion((v as string) || '')}
                  sx={{ minWidth: 160 }}
                >
                  <Option value="">From the file</Option>
                  {active.motions.map(t => <Option key={t} value={t}>{t}</Option>)}
                </Select>
              )}
              <Button
                size="sm"
                onClick={() => fetchPresentation()}
                disabled={!selectedFile || loading}
                loading={loading}
              >
                Generate
              </Button>
              {selectedFile && (
                <Button
                  size="sm"
                  variant="outlined"
                  color="neutral"
                  startDecorator={<EditIcon sx={{ fontSize: 14 }} />}
                  onClick={() => setEditorOpen(true)}
                >
                  Edit File
                </Button>
              )}
            </>
          )}
        </Box>
      </Sheet>

      {/* Error */}
      {error && (
        <Sheet variant="soft" color="danger" sx={{ borderRadius: 'sm', p: 2 }}>
          <Typography level="body-sm">{error}</Typography>
        </Sheet>
      )}

      {/* Loading */}
      {loading && (
        <Box sx={{ display: 'flex', justifyContent: 'center', p: 4 }}>
          <CircularProgress />
        </Box>
      )}

      {/* Presentation iframe */}
      {htmlContent && !loading && (
        <Sheet
          variant="outlined"
          sx={{
            borderRadius: 'sm',
            overflow: 'hidden',
            flex: 1,
            minHeight: 500,
          }}
        >
          <iframe
            ref={iframeRef}
            title="Presentation Preview"
            sandbox="allow-scripts allow-same-origin"
            style={{
              width: '100%',
              height: '100%',
              border: 'none',
              minHeight: 500,
            }}
          />
        </Sheet>
      )}

      {/* Bottom controls */}
      {htmlContent && !loading && (
        <Sheet variant="outlined" sx={{ borderRadius: 'sm', p: 2 }}>
          <Box sx={{ display: 'flex', gap: 2, flexWrap: 'wrap', alignItems: 'center' }}>
            <Button
              size="sm"
              variant="solid"
              startDecorator={<OpenInNewIcon />}
              onClick={handleOpenInNewTab}
            >
              Open Fullscreen
            </Button>
            <Button
              size="sm"
              variant="solid"
              startDecorator={<SaveIcon />}
              onClick={handleSave}
            >
              Save as HTML
            </Button>
            <Typography level="body-xs" sx={{ color: 'text.tertiary', ml: 'auto' }}>
              {active.label} &middot; {active.note}
            </Typography>
          </Box>
        </Sheet>
      )}

      {!htmlContent && !loading && !error && (
        <Box sx={{ textAlign: 'center', p: 4 }}>
          <Typography level="body-md" sx={{ color: 'text.secondary' }}>
            Search for an org file and click Generate to create a presentation.
          </Typography>
        </Box>
      )}

      {/* File editor modal */}
      {selectedFile && (
        <OrgEditor
          open={editorOpen}
          onClose={() => setEditorOpen(false)}
          mode="file"
          filename={selectedFile}
        />
      )}
    </Box>
  );
}
