// The gantt chart drawn by Google Charts.
//
// The one that knows what a project *is*: it draws the dependency arrows
// itself, fills each bar by how much of it is done, and will work out and paint
// the critical path - the chain of tasks where a day's slip is a day off the end
// of the whole plan. Nothing else here can do that.
//
// What it cannot do is be dragged: Google's gantt has no editing gestures at
// all, and its only event is "a row was selected". So this chart selects, and
// everything that changes the plan happens in the panel beside it - which is the
// same panel the other two charts use, so nothing is missing, only moved.
//
// It is also the only renderer that needs the network at runtime: the loader
// and the chart code come from gstatic, and there is no offline build of it. A
// worg served from an orgs binary on a machine with no internet says so rather
// than sitting blank.

import * as React from 'react';
import Typography from '@mui/joy/Typography';
import CircularProgress from '@mui/joy/CircularProgress';
import Box from '@mui/joy/Box';
import useScript from '../useScript';
import { GanttModel, GanttTask, GanttMarker, dayKey, SHAPE_GLYPH } from '../gantt';
import { GanttColors, MarkerLook } from './ReactGantt';
import {
    paintBarGradients, paintGround, paintType, shade, legibleOn, veilOn, FONT_UI, TYPE,
} from '../ganttstyle';
import { ColorScheme } from '../ganttcolor';

const LOADER = 'https://www.gstatic.com/charts/loader.js';
const DAY_MS = 86400000;

declare global {
    interface Window { google?: any; }
}

// Google colours a bar by its *resource* and has no way at all to colour one bar
// on its own - so every task is put in a bucket named after the colour the
// scheme gives it, and the palette is built to match. Nothing on the chart shows
// a resource name, so this buys any colouring we like without costing anything.


export default function GoogleGantt({
    model,
    colors,
    scheme,
    selected,
    criticalPath,
    markers,
    markerLook,
    onSelect,
}: {
    model: GanttModel;
    colors: GanttColors;
    scheme: ColorScheme;
    selected?: string;
    criticalPath: boolean;
    // Google's gantt has nowhere to draw a line down the chart, so the
    // markers are listed under it in their own colour instead.
    markers?: GanttMarker[];
    markerLook?: MarkerLook;
    onSelect?: (t: GanttTask) => void;
}) {
    const status = useScript(LOADER);
    const [ready, setReady] = React.useState(false);
    const [err, setErr] = React.useState('');
    const boxRef = React.useRef<HTMLDivElement>(null);
    const live = React.useRef({ model, onSelect });
    live.current = { model, onSelect };

    React.useEffect(() => {
        if (status !== 'ready' || !window.google) return;
        let alive = true;
        try {
            window.google.charts.load('current', { packages: ['gantt'] });
            window.google.charts.setOnLoadCallback(() => { if (alive) setReady(true); });
        } catch (e: any) {
            setErr(e?.message || 'could not load the Google charts package');
        }
        return () => { alive = false; };
    }, [status]);

    React.useEffect(() => {
        if (!ready || !boxRef.current || !window.google || !window.google.visualization) return;
        const g = window.google.visualization;

        const drawn = model.tasks.filter(t => !t.mark);
        const known = new Set(drawn.map(t => t.id));

        const data = new g.DataTable();
        data.addColumn('string', 'Task ID');
        data.addColumn('string', 'Task Name');
        data.addColumn('string', 'Resource');
        data.addColumn('date', 'Start');
        data.addColumn('date', 'End');
        data.addColumn('number', 'Duration');
        data.addColumn('number', 'Percent Complete');
        data.addColumn('string', 'Dependencies');

        const bucketOf = (t: GanttTask) => scheme.color(t);
        const buckets: string[] = [];
        for (const t of drawn) {
            const b = bucketOf(t);
            if (buckets.indexOf(b) < 0) buckets.push(b);
        }

        data.addRows(drawn.map(t => {
            // A milestone has no width, and Google draws a zero-length bar as
            // nothing at all - so it gets the day it is on and is filled in.
            const end = t.milestone ? new Date(t.start.getTime() + DAY_MS) : t.end;
            return [
                t.id,
                t.name,
                bucketOf(t),
                t.start,
                end,
                null,
                t.milestone ? 100 : Math.max(0, Math.min(100, t.percent || 0)),
                t.after.filter(a => known.has(a)).join(',') || null,
            ];
        }));

        // Every bucket *is* a colour now, so the palette is the buckets.
        const palette = buckets.map(b => ({ color: b, dark: shade(b, -0.25), light: shade(b, 0.45) }));

        const options = {
            height: Math.max(140, drawn.length * 34 + 60),
            backgroundColor: colors.background,
            gantt: {
                trackHeight: 34,
                barHeight: 18,
                barCornerRadius: 3,
                criticalPathEnabled: criticalPath,
                criticalPathStyle: { stroke: colors.taskCrit, strokeWidth: 2 },
                arrow: { angle: 45, width: 1.4, color: veilOn(colors.background, 0.55), radius: 0 },
                innerGridHorizLine: { stroke: veilOn(colors.background, 0.16), strokeWidth: 0.4 },
                innerGridTrack: { fill: colors.background },
                innerGridDarkTrack: { fill: colors.sectionAlt },
                labelStyle: {
                    fontName: FONT_UI,
                    fontSize: TYPE.task.size,
                    color: legibleOn(colors.text, colors.background),
                },
                percentEnabled: true,
                shadowEnabled: false,
                palette,
            },
        };

        const chart = new g.Gantt(boxRef.current);
        // The colours we asked for, which is how a bar is told from everything
        // else Google draws.
        const wanted = palette.map(p => p.color);

        const box = boxRef.current;
        g.events.addListener(chart, 'ready', () => {
            if (!box) return;
            paintGround(box, colors.background, wanted);
            paintBarGradients(box, wanted, 'gg');
            paintType(box, { on: colors.background, onBars: wanted });
        });
        g.events.addListener(chart, 'select', () => {
            const sel = chart.getSelection();
            if (!sel || sel.length === 0) return;
            const id = data.getValue(sel[0].row, 0);
            const t = live.current.model.tasks.find(x => x.id === id);
            if (t && live.current.onSelect) live.current.onSelect(t);
        });
        g.events.addListener(chart, 'error', (e: any) => setErr((e && e.message) || 'the chart could not be drawn'));

        try {
            chart.draw(data, options);
            setErr('');
        } catch (e: any) {
            setErr(e?.message || 'the chart could not be drawn');
        }

        // Google redraws from scratch every time, so the selection is put back
        // after each draw rather than kept by the chart.
        if (selected) {
            const row = drawn.findIndex(t => t.id === selected);
            if (row >= 0) chart.setSelection([{ row, column: null }]);
        }
    }, [ready, model, colors, scheme, criticalPath, selected]);

    if (status === 'error') {
        return (
            <Typography level="body-sm" sx={{ color: 'danger.500', p: 2 }}>
                Google Charts could not be loaded. This renderer fetches its code from
                gstatic.com, so it needs the network; the other three do not.
            </Typography>
        );
    }
    if (!ready) {
        return (
            <Box sx={{ display: 'flex', alignItems: 'center', gap: 1.5, p: 2 }}>
                <CircularProgress size="sm" />
                <Typography level="body-sm">Loading Google Charts</Typography>
            </Box>
        );
    }
    return (
        <Box>
            {err && <Typography level="body-xs" sx={{ color: 'danger.500', mb: 1 }}>{err}</Typography>}
            <div ref={boxRef} />
            {model.tasks.some(t => t.mark) && (
                <Typography level="body-xs" sx={{ color: 'text.tertiary', mt: 1 }}>
                    {model.tasks.filter(t => t.mark).map(t => `${t.name} (${t.start.toDateString()})`).join('  ')}
                </Typography>
            )}
            {markers && markers.length > 0 && (
                <Box sx={{ display: 'flex', flexWrap: 'wrap', gap: 1.5, mt: 1 }}>
                    {markers.map((m, i) => (
                        <Typography key={i} level="body-xs" sx={{
                            color: 'text.secondary', pl: 1,
                            borderLeft: `${Math.max(1, markerLook?.width || 2)}px ${markerLook?.style === 'dotted' ? 'dotted' : markerLook?.style === 'solid' ? 'solid' : 'dashed'} ${m.color || markerLook?.color || '#8e44ad'}`,
                        }}>
                            {m.shape && m.shape !== 'none' && (
                                <span style={{ color: m.color || markerLook?.color || '#8e44ad', marginRight: 4 }}>
                                    {SHAPE_GLYPH[m.shape]}
                                </span>
                            )}
                            {`${m.name} · ${dayKey(m.date)}${m.end ? ` → ${dayKey(new Date(m.end.getTime() - 1))}` : ''}`}
                        </Typography>
                    ))}
                </Box>
            )}
        </Box>
    );
}
